package com.indianservers.krishna4u.feature.letters

import androidx.annotation.DrawableRes
import com.indianservers.krishna4u.R

private fun simpleEnglish(text: String): String = listOf(
    "qualified medical care" to "care from a trained doctor",
    "qualified support" to "trained help",
    "qualified help" to "trained help",
    "professional support" to "trained help",
    "nonessential" to "not needed",
    "interrogation" to "too many questions",
    "self-betrayal" to "betraying yourself",
    "consistent behaviour" to "steady actions",
    "independently" to "on your own",
    "circumstances" to "situations",
    "circumstance" to "situation",
    "unmanageable" to "too heavy to carry",
    "depleted" to "very tired",
    "manufacture" to "force",
    "recognition" to "praise",
    "possessiveness" to "the need to control",
    "possessive" to "controlling",
    "exploits" to "takes advantage of",
    "exploit" to "take advantage of"
).fold(text) { result, (formal, simple) -> result.replace(formal, simple, ignoreCase = true) }

private fun conciseClosing(text: String): String = text
    .split(Regex("(?<=[.!?])\\s+"))
    .take(2)
    .joinToString(" ")

data class KrishnaLetter(val id: String, val situation: String, val title: String, val preview: String, val paragraphs: List<String>, val reflection: String, val nextStep: String, @param:DrawableRes val icon: Int) {
    val readingParagraphs: List<String>
        get() = paragraphs.mapIndexed { index, paragraph ->
            simpleEnglish(if (index == paragraphs.lastIndex) conciseClosing(paragraph) else paragraph)
        }

    fun personalizedReadingParagraphs(name: String): List<String> {
        val readerName = name.trim().ifBlank { "Seeker" }
        return readingParagraphs.mapIndexed { index, paragraph ->
            if (index != 0) paragraph
            else if (paragraph.startsWith("My dear one,", ignoreCase = true)) {
                paragraph.replaceFirst(Regex("^My dear one,", RegexOption.IGNORE_CASE), "My dear $readerName,")
            } else {
                "My dear $readerName, $paragraph"
            }
        }
    }

    fun spokenText(name: String): String = "${personalizedReadingParagraphs(name).joinToString(" ")} Remember: $reflection I am with you, Krishna."
    val audiences: Set<String> get() = audiencesForKrishnaLetter(id)
}

val krishnaLetterAudiences = listOf(
    "Children", "Students", "Youth", "Parents", "Professionals", "Couples", "Elders",
    "Grief & Illness", "Caregivers", "Leaders", "Spiritual Seekers", "New Beginnings"
)

private fun audiencesForKrishnaLetter(id: String): Set<String> = buildSet {
    if (id in setOf("embarrassed", "bored", "belonging", "child-truth", "left-out-school")) add("Children")
    if (id in setOf("failure", "anxiety", "not-enough", "comparison", "future-fear", "student-focus", "important-exam", "comfort-growth", "happiness-before-duty", "smart-work", "rise-again", "stronger-than-moment", "life-purpose", "choose-courage", "ready-to-grow", "walk-dharma", "dream-discipline", "valuable-gift", "future-still-open", "next-step-strength")) add("Students")
    if (id in setOf("rejection", "uncertainty", "heart-broken", "misunderstood", "anger", "comparison", "change", "youth-peer-pressure", "identity-confusion", "moving-on", "comfort-growth", "happiness-before-duty", "pain-strength", "smart-work", "someone-only-takes", "presence-costs-peace", "returning-to-hurt", "friendship-changed", "outgrown-place", "guilty-choosing-self", "memories-pull-back", "closure-never-came", "rise-again", "stronger-than-moment", "life-purpose", "choose-courage", "ready-to-grow", "walk-dharma", "dream-discipline", "valuable-gift", "future-still-open", "next-step-strength")) add("Youth")
    if (id in setOf("family-struggling", "carrying-too-much", "guilt", "parent-failing", "child-pulls-away")) add("Parents")
    if (id in setOf("failure", "financial-struggle", "success", "proud", "confident", "inspired", "work-taken-over", "work-unseen", "comfort-growth", "happiness-before-duty", "smart-work", "rise-again", "stronger-than-moment", "life-purpose", "choose-courage", "ready-to-grow", "walk-dharma", "dream-discipline", "valuable-gift", "future-still-open", "next-step-strength")) add("Professionals")
    if (id in setOf("heart-broken", "betrayal", "letting-go", "loved", "couple-arguments", "rebuilding-trust", "moving-on", "someone-only-takes", "presence-costs-peace", "returning-to-hurt", "guilty-choosing-self", "closure-never-came", "love-trust-gone")) add("Couples")
    if (id in setOf("forgotten", "health-failing", "grateful", "peaceful", "elder-invisible", "depending-on-others")) add("Elders")
    if (id in setOf("grief", "lost-hope", "health-failing", "tired-strong", "grief-returns", "caring-for-ill", "pain-strength", "memories-pull-back", "beginning-betrays-past")) add("Grief & Illness")
    if (id in setOf("family-struggling", "carrying-too-much", "health-failing", "caring-for-ill")) add("Caregivers")
    if (id in setOf("difficult-decision", "anger", "success", "confident", "leader-decision", "choose-courage", "walk-dharma", "valuable-gift")) add("Leaders")
    if (id in setOf("unanswered-prayers", "lost-purpose", "hopeful", "peaceful", "grateful", "faith-dry", "life-purpose", "walk-dharma", "valuable-gift", "next-step-strength")) add("Spiritual Seekers")
    if (id in setOf("stuck", "change", "begin-again", "hopeful", "inspired", "disappointed", "new-place", "moving-on", "comfort-growth", "pain-strength", "smart-work", "friendship-changed", "outgrown-place", "guilty-choosing-self", "memories-pull-back", "closure-never-came", "love-trust-gone", "beginning-betrays-past", "rise-again", "stronger-than-moment", "ready-to-grow", "future-still-open", "next-step-strength")) add("New Beginnings")
    if (isEmpty()) add("Youth")
}

private fun krishnaPersonalTouch(id: String): String = when (id) {
    "anxiety" -> "When your breath becomes fast, call Me quietly and return to the breath in front of you. I am not standing at the end of every problem, waiting for you to solve it alone. I am here in this minute. Let Me hold the future while you care for the one small duty that belongs to today."
    "lost-hope" -> "If you cannot carry hope today, let Me carry it for you. Your only work may be to stay, drink water, open the curtain and tell a safe person that the darkness feels heavy. These are not small acts to Me. Each one says that pain will not be allowed to write your final page."
    "heart-broken" -> "Give Me the memories you keep touching and the questions that have no answer. I will not ask you to stop loving in one day. I will help you love without abandoning yourself. Each time you choose food, sleep, truth and dignity, you are walking back toward the heart I placed within you."
    "not-enough" -> "Look at yourself for one moment through My eyes. I see a soul learning, not a product waiting to be approved. Bring Me your weak places without hiding them. We will work on what can grow, but I will not let a cruel inner voice pretend to be wisdom. You are worthy while you are still becoming."
    "misunderstood" -> "Even when your words come out badly, I know the truth you were trying to carry. Sit with Me, make the words simpler and try again with someone safe. You do not need every person to understand you. You need the courage to speak honestly, listen humbly and remain close to who you truly are."
    "future-fear" -> "You keep walking into tomorrow in your mind and returning tired. Come back to Me. Tomorrow has not asked for your strength yet. I will meet you there when it arrives, just as I am meeting you here. Prepare one useful thing, then place the unopened hours in My hands and let your body rest."
    "life-unfair" -> "I will not call injustice a blessing just to make your pain quiet. Tell the truth, seek help and protect yourself without becoming what hurt you. Stand beside Me in dharma: firm without cruelty, brave without hatred. What happened matters, and so does the person you choose to become after it."
    "tired-strong" -> "Come sit beside Me without explaining why you are tired. You have carried enough for this moment. Let another person help, let one task wait and let your body soften. I do not love you more when you suffer silently. Rest can also be an act of trust, and receiving care can also be courage."
    "self-forgiveness" -> "Do not bring Me the same mistake each day as proof that you must remain punished. Bring Me the truth, the repair and the person you are choosing to become. If you have corrected what you can, walk forward with humility. I remember your lesson; I do not need you to keep wearing your wound."
    "betrayal" -> "I know why your heart now checks every door twice. Do not force it to trust before safety is clear. Let Me help you build wise limits without turning every new person into the one who hurt you. Their dishonesty belongs to their choice; your future can still belong to truth, courage and clean love."
    "letting-go" -> "Place their name in My hands when holding it begins to hurt you. You do not have to erase the good or deny the pain. Bless what was true, learn from what was not and loosen your grip one day at a time. I will walk beside the empty space until new life can enter it gently."
    "family-struggling" -> "I see how quickly you listen for every problem in the house. My dear one, you are a member of this family, not its only rescuer. Do your honest part, speak with care and ask responsible people to carry theirs. Give Me the burdens no child or single heart was meant to hold alone."
    "stuck" -> "You are looking for a great door while I am pointing to one small step. Wash, write, call, walk or begin for five minutes. Movement does not need to look impressive to be real. Take My hand through the ordinary action in front of you, and let today be a little different from yesterday."
    "unanswered-prayers" -> "Speak to Me even if your prayer is only, ‘I do not understand.’ You do not have to use beautiful words or pretend that silence does not hurt. I am present in the waiting, in wise help and in the strength to continue. Keep your heart open, but let your hands also do the next right thing."
    "difficult-decision" -> "Bring Me both choices without hiding the part you secretly want. We will look at truth, duty, harm and the people who may carry the result. My guidance will not always feel like the easiest road. Often it is the quiet path that lets you keep your honesty after the fear and excitement have passed."
    "lost-purpose" -> "Do not wait for a grand sign before you call your life meaningful. I am often found in the person who needs listening, the work that needs care and the promise that needs keeping. Serve what is near with your full heart. Purpose may first arrive dressed as a small duty you almost ignored."
    "anger" -> "Bring Me the fire before you throw it at someone. I will not shame you for feeling it, but I will ask you not to let it burn your wisdom. Cool your body, tell Me what was hurt and choose words that protect truth without creating a new wound. That pause is strength, not defeat."
    "comparison" -> "When another person shines, do not turn their light against yourself. I did not write your life as a copy of theirs. Bless their good, then come back to the work I placed in your hands. Your pace may be different, but every honest step still reaches Me. There is room for both of you to grow."
    "change" -> "You may hold the old life with one hand while reaching for the new with the other. I understand. You do not have to cross the whole distance today. Carry your values, keep one steady practice and take My hand for the next unfamiliar step. I am already present in the place you are afraid to enter."
    "carrying-too-much" -> "Open your hands before Me and name each weight. Some are duties, some can be shared and some were never yours. I do not ask you to prove love by breaking yourself. Keep what is truly yours, seek help for what is heavy and return the rest. A lighter heart can serve more faithfully."
    "forgotten" -> "I have not confused quietness with worth. I see the meal you prepared, the message you sent, the work nobody praised and the care you gave when you were tired. Ask clearly for the company you need, but do not let silence erase your value. Your unseen goodness still leaves light in this world."
    "financial-struggle" -> "Bring Me the numbers as they are, not as fear keeps shouting them. We will not solve them through shame or a dangerous shortcut. Choose honesty, wise advice and the next practical step. Your money can change; your dignity does not. I am beside you in careful planning, patient work and every clean beginning."
    "health-failing" -> "I am with you in this body today, not only in the healthy body you remember or hope to regain. Let skilled care, medicine, rest and loving hands reach you. You are not a burden because you need help. Your presence, voice and love still carry meaning, even on a day when little can be done."
    "begin-again" -> "Do not ask whether you can promise Me a perfect future. Promise only the next honest step. If you fall, return without hiding from Me. I am not counting how many times you needed to begin; I am watching the courage with which you return to truth. Let us start from where your feet are now."
    "happy" -> "Bring Me your laughter too, not only your tears. I delight in joy that is clean, grateful and kind. Let nobody’s pain become your entertainment and nobody’s fall become your victory. Invite another heart into the light you feel today. Happiness shared without pride becomes a small blessing moving through the world."
    "grateful" -> "When you whisper thank you, I hear more than words. I see whether you protect the gift, honour the hands behind it and remember those who have less. Let gratitude change one action today. Care for what you received and pass some goodness forward; then your thanks becomes a living prayer."
    "success" -> "I was beside you during the quiet practice long before anyone saw the result. Celebrate, my dear one, but keep room beside you for the people who helped and those still trying. Let success enlarge your service rather than your ego. The finest offering is to use your new strength without forgetting tenderness."
    "proud" -> "I am glad you can finally see your growth. Hold that pride like a lamp, not a crown. Let it show what patient effort can do, but never use it to place another soul below you. I care more for the honesty behind your progress than for applause. Keep learning, and keep your heart easy to approach."
    "excited" -> "I can feel how quickly your thoughts are running. Tell Me every bright possibility, then sit with Me long enough to see the whole path. Check the facts, the cost and your duty before you leap. I do not want to dim your spark; I want to help it become a steady flame that can finish good work."
    "peaceful" -> "Stay with Me in this quiet for a little longer. You do not need to fill it or explain it. Let calm wash the dust from your judgment, then carry it into your next conversation and duty. Peace is not hiding from life; it is meeting life without allowing noise to command your heart."
    "loved" -> "Receive this love without testing it until it breaks. I am present wherever care is honest, safe and free. Cherish the person, but do not make them your possession or your only source of worth. Let being loved teach you how to listen, respect limits and offer the same gentleness without fear."
    "hopeful" -> "This small light in you is precious to Me. Protect it with truth and action, not fantasy alone. Take one step and let the road answer slowly. If the path changes, hope has not betrayed you; it may be leading you toward a wiser door. I will meet you in every sincere attempt."
    "relieved" -> "Now breathe, my dear one. You do not have to keep danger alive in your mind after it has passed. Thank the help that reached you and keep the lesson that protected you. Finish any repair still needed, then allow yourself to rest. I am with you in the soft silence after the storm."
    "confident" -> "Stand with Me and use your strength well. Speak clearly, attempt the hard work and protect the person whose voice is ignored. But keep listening; I may send wisdom through someone younger, quieter or less powerful than you. Confidence remains beautiful when it can learn, apologise and share the light. Let your courage make the path safer for the person walking after you."
    "inspired" -> "I placed this spark in your attention; now honour it with practice. Begin before the feeling fades, and return when the work becomes ordinary. Ask whether your idea serves truth or only your image. If it can teach, protect, heal or create honest beauty, give it your disciplined hands and let Me walk through the work with you."
    "belonging" -> "I am glad you have found a circle where your heart can rest. Now notice who is standing just outside it. Do not protect belonging through gossip, cruelty or exclusion. Make room without losing truth. Each time you help another person feel safely seen, you turn a group into a community where I can be felt."
    "disappointed" -> "Tell Me exactly what you hoped would happen. I will not laugh at the size of your hope or hurry you past the hurt. Together we will separate the fact from fear, learn what is ours to learn and choose whether to try, change or release. One closed result does not close My care for you."
    "embarrassed" -> "Come out from the moment your mind keeps replaying. I saw it, and I still see the whole of you. Repair any harm, learn one lesson and let the rest become human imperfection. You do not need to disappear. Take My hand and return to the room with a little more humility and a little less fear."
    "bored" -> "Before you run toward more noise, sit with Me and ask what this emptiness needs. It may be rest, challenge, movement, company or meaning. Give one simple thing your full attention. I often hide wonder inside ordinary duties, quiet nature and the chance to help. Look again before you call the moment empty."
    "homesick" -> "I know the voices, smells and small habits your heart is reaching for. Carry them with love, but do not close the door to where you stand now. I travelled with you. Keep one piece of home alive and take one brave step toward a new bond. Your roots can deepen while your branches learn a new sky."
    "child-truth" -> "Come to Me with the truth, even if your voice shakes. A mistake can be repaired more easily than a story built to hide it. I do not call you bad because you were afraid. Tell a safe adult what happened, accept a fair repair and let honesty make your heart lighter again."
    "left-out-school" -> "I see you standing at the edge and wondering what is wrong with you. Their circle is not the measure of your worth. Stay kind without begging for a place that needs you to become cruel. Tell a safe adult if exclusion keeps hurting, and look for one person who also needs a gentle hello."
    "student-focus" -> "Bring Me the restless mind, not a promise to become perfect tomorrow. We will make the work small: one clear task, one quiet space and one short period of full attention. When the mind wanders, return without insult. Every return is practice, and practice slowly becomes strength."
    "important-exam" -> "Place the result in My hands and keep the preparation in yours. This exam can measure some answers on one day; it cannot measure your whole mind, heart or future. Sleep, breathe and read the next question carefully. I will be beside you before, during and after the result."
    "youth-peer-pressure" -> "You do not owe the crowd your health, body, honesty or future. A true friend will not demand that you betray yourself to prove belonging. Say no, leave and call someone safe if you need help. I would rather see you stand alone in dharma than disappear inside borrowed approval."
    "identity-confusion" -> "You are allowed to be unfinished. Do not rush to wear a label only because uncertainty feels uncomfortable. Notice your values, gifts, responsibilities and the people with whom you can be honest. I am not waiting for a perfect definition of you; I am walking with the real person still discovering their path."
    "parent-failing" -> "I do not ask you to be a parent who never makes mistakes. I ask you to notice, apologise, repair and return. Your child needs your presence more than a perfect image. Put down comparison, seek wise help and change one response today. Love can become stronger when humility enters the home."
    "child-pulls-away" -> "Do not chase every silence with fear or control. Growing children need space, but they still need a door that opens without shame. Stay interested without interrogation. Keep reasonable safety limits and offer small moments of connection. I am with you while love learns a new distance and a new language."
    "work-taken-over" -> "Your work is part of your duty; it is not the whole of your life. I also meet you in sleep, health, family, silence and the person you become away from achievement. Close one unfinished door for tonight. No title is worth losing the heart, body and relationships it was meant to support."
    "work-unseen" -> "I see the careful work that received no praise and the responsibility you carried without display. Human recognition may be late or absent, but do not let bitterness corrupt your offering. Ask clearly for fair feedback or credit where needed, then keep your character larger than the applause you did not receive."
    "couple-arguments" -> "I am present in the pause where both of you stop trying to win. Speak about the wound without attacking the person. Listen for the need beneath the words and take time apart if anger becomes unsafe. Love is not proved by never disagreeing; it is protected by how truth and repair enter disagreement."
    "rebuilding-trust" -> "Trust cannot be ordered back through one apology. Let truth become consistent, let questions receive patient answers and let boundaries remain while the wound heals. If you caused harm, do not rush the other heart. If you were harmed, you may forgive without pretending safety has already returned."
    "elder-invisible" -> "Your speed may have changed, but your soul has not become smaller. I see the years, losses, service and wisdom that others may hurry past. Ask for the respect and company you need. Keep offering your voice where it is welcomed, and remember that dignity does not retire when public attention moves elsewhere."
    "depending-on-others" -> "Receiving help does not erase the life in which you helped many others. Let care reach you without calling yourself a burden. Name your preferences, keep the choices you can and thank the hands that serve with love. Your worth was never based only on how independently you could move."
    "caring-for-ill" -> "I see the appointments, interrupted sleep and quiet fear that others may not notice. Service is sacred, but you are not required to disappear inside it. Ask for relief, eat, rest and let another person carry part of the load. I am beside both the one who suffers and the one who stays."
    "grief-returns" -> "This returning wave does not mean you have failed to heal. Love can be quiet for months and then speak through a date, song or familiar place. Let the tears come without judging the progress between them. Sit with Me, share the memory and care gently for the life still asking for you today."
    "leader-decision" -> "Before people follow your decision, bring Me the power it carries. Listen especially to those who will bear the cost but hold less authority. Choose truth over image and welfare over ego. Leadership is not proved by always appearing certain; it is proved by taking responsibility for a careful and just choice."
    "faith-dry" -> "You do not have to manufacture a feeling to remain close to Me. Bring Me the quiet prayer, the unanswered question and even the doubt. Devotion can be a small honest action when emotion is absent. Keep one gentle practice, serve someone near you and let love return in its own time."
    "moving-on" -> "Place the person, the memories and the questions in My hands. Take the lesson with you, but leave the weight behind. I am not only present in what stays. I am also present in the courage that helps you move on."
    "comfort-growth" -> "Do not ask Me to remove every hill from your road. Ask Me for the strength, wisdom and good people needed to climb the hill that belongs to you. I will give you rest when you need it, but I will also call you forward when comfort asks you to stay small."
    "happiness-before-duty" -> "You do not have to feel happy before you walk with Me. Bring Me the tired heart and the unfinished duty. We can take one honest step together, and sometimes peace will meet you after you begin rather than before."
    "pain-strength" -> "Do not hide your pain from Me or turn it into your whole identity. Let us understand what it asks for: care, change, courage or release. You are not weak because something hurts; you become stronger when you answer pain with truth and a healthy step."
    "smart-work" -> "I do not measure devotion by how tired you can make yourself. Bring Me effort joined with thought. Learn from a Guru, teacher or skilled person, remove wasted work and give your full attention to what truly moves the duty forward."
    "someone-only-takes" -> "You may care without making your heart an endless storehouse for another person. Bring Me the guilt that rises when you say no. Love can give freely, but dharma also asks for truth, balance and respect for the life I placed in your care."
    "presence-costs-peace" -> "I do not ask you to call every hard talk harmful, but I also do not ask you to live inside repeated fear and disrespect. Let truth show you the pattern. Peace is not silence at any cost; sometimes peace begins with a clear limit and a safe distance."
    "returning-to-hurt" -> "Do not be ashamed that you returned. Familiar pain can feel easier than an unknown future. Come back to Me now, tell a safe person the whole pattern and let this return become the moment you choose help instead of another promise without change."
    "friendship-changed" -> "Some friendships walk closely for one season and softly change in another. Do not turn every distance into an enemy story. Keep what was good, speak once with honesty and let both lives grow without forcing yesterday to return."
    "outgrown-place" -> "Growth may make an old room feel too small, but do not leave with pride. Thank the place that held an earlier version of you. Carry its lesson, honour the people who helped and step toward the wider duty now calling you."
    "guilty-choosing-self" -> "Choosing your health, safety and honest limits is not the same as caring only about yourself. Bring Me the guilt and examine it with truth. Keep your real duties, but do not accept a false duty to disappear so that everyone else remains comfortable."
    "memories-pull-back" -> "A memory can be a lamp without becoming a chain. Sit with Me when the old scene returns. Bless what was true, notice what is true now and give today at least one act of your full attention."
    "closure-never-came" -> "You may never receive the apology or answer that would make the story neat. Do not give another person lifelong control over your peace by waiting at that closed door. We can build closure from truth, wise limits and the life you choose next."
    "love-trust-gone" -> "Love can remain after safety has broken. Do not use love as proof that trust must return at once. Let actions, time and honest repair decide what access is safe, and let distance remain if the harm continues."
    "beginning-betrays-past" -> "Moving forward does not erase the person, dream or life you loved. Take the best of the past with you as a value, not a weight. I am present in your memory, and I am also waiting in the new morning you are learning to enter."
    "rise-again" -> "Rise, My dear one. Do not try to prove everything in one day. Give Me yesterday's weight, keep its lesson and take one honest step. I am not watching from far away; I am rising with you."
    "stronger-than-moment" -> "This moment may be loud, but it is not greater than the strength I placed within you. Let Me hold the future while you do the next right thing. The moment will pass, and the courage you build here will remain."
    "life-purpose" -> "Do not wait for a grand sign before you serve. I meet you in the duty near you, the person who needs care and the gift you use honestly. Walk with Me, and let your simple actions reveal why your life matters."
    "choose-courage" -> "When your voice shakes, remember that I hear it. Stand for dharma without anger and protect without cruelty. You are not alone when you choose what is right; I am beside you in the brave step."
    "ready-to-grow" -> "Bring Me the weakness you want to change without shame. I do not expect perfection; I ask for honesty, practice and a willing heart. Keep moving toward the light I placed before you, one steady choice at a time."
    "walk-dharma" -> "If the right road feels lonely, take My hand. Do not trade your values for quick approval. The peace of a clean heart will remain after the crowd has moved on, and I will walk every step with you."
    "dream-discipline" -> "Give Me your dream, then honour it through today's work. I am with you not only in bright inspiration but also in the quiet practice nobody sees. Keep the effort in your hands and place the result in Mine."
    "valuable-gift" -> "I placed something useful within you, and it does not need to look like another person's gift. Learn it well, offer it without pride and let it serve life. I can bring light through your time, attention, skill and kindness."
    "future-still-open" -> "One result cannot close the future I have placed before you. Learn, change your method and prepare again, or notice the wiser door now opening. Do not stop walking because one road ended; I am already present on the next one."
    "next-step-strength" -> "You do not need to see the whole road to walk with Me. Begin with the truth you know and the duty before you. My presence is not a reason to remain still; it is the strength that helps you take the next step."
    else -> error("Missing Krishna-style personal touch for letter: $id")
}

private fun personalLetter(id: String, situation: String, title: String, preview: String, first: String, second: String, third: String, reflection: String, nextStep: String, icon: Int) = KrishnaLetter(
    id, situation, title, preview,
    listOf(
        first,
        second,
        third,
        krishnaPersonalTouch(id)
    ), reflection, nextStep, icon
)

val krishnaLetters = listOf(
    KrishnaLetter("failure", "When You Feel You Have Failed", "You Are More Than One Result", "This result may hurt, but it cannot decide who you are.", listOf(
        "My dear one, I know this hurts. You hoped, worked and waited. Now one result is making you question yourself. Please hear Me: you faced a hard moment. You are not a failure. A mark, a job or a win can tell you what happened today. It cannot tell you how much good, courage and promise live in you.",
        "I will not shame you for falling. I will help you see the next right step. Look at your effort with honesty. Keep what worked. Learn what did not. Ask a teacher, elder or trustworthy Guru for guidance where you cannot see clearly. A good Guru does not carry your duty for you; they help you understand, practise and rise with wiser eyes. This is not the end of your story. It is one page that can make you wiser.",
        "You do not have to prove your worth to begin again. You already deserve care, hope and another chance. Rest for a while. Then take one small step with your full heart. I am not waiting only at your success. I am beside you while you rise.",
        "One day, you may look back and see that this result did not break you. It taught you how to prepare, ask, wait and try again. For today, do not carry the whole future. Carry only the next small task. I believe you can do that."
    ), "What did this result teach you about your method, not your worth?", "Write one lesson and do one small thing today that will help your next try.", R.drawable.icon_courage),
    KrishnaLetter("loneliness", "When Loneliness Feels Heavy", "You Are Not Forgotten", "The quiet feels empty, but your life still holds love and a place for you.", listOf(
        "My dear one, I know the pain of feeling unseen. You may be in a room full of people and still feel alone. Your mind may say, ‘No one needs me.’ That thought comes from pain. It is not the full truth. Your need for love is not weakness. Your heart was made to give and receive care.",
        "When the world feels far away, sit with Me for one quiet minute. Then do not hide there forever. Tell one safe person, ‘I need someone to talk to.’ Join your family for tea. Call a friend. Help someone who also feels left out. A true bond often starts with one small, brave hello.",
        "If one person does not answer, do not make it a judgment on your worth. Keep reaching for safe people. You deserve support. If the sadness feels too heavy or you feel unsafe, tell a trusted adult or trained helper now. Help is one of the ways My care reaches you.",
        "There is still a place for your voice, your smile and your care. The right bonds may take time to grow. Do not close your heart because today is quiet. Take one gentle step toward life, and let someone take one step toward you."
    ), "What kind of care do you need most today: a talk, company, comfort or help?", "Send one honest message to a safe person and ask for ten minutes together.", R.drawable.icon_friendship),
    KrishnaLetter("grief", "When You Are Grieving", "Your Love Is Still Real", "You do not need to rush your tears or forget what mattered.", listOf(
        "My dear one, you miss someone or something you loved. That empty space is real. You do not need to act strong every hour. Tears do not make you weak. They show that your love was true. I can sit with you even when you have no words or prayers.",
        "Some days may feel calm. Then a song, place or small memory may bring the pain back. This does not mean you are failing to heal. Grief moves like waves. Let safe people stay near you. Say the name you miss. Share a good memory. Eat, rest and care for the life that is still in your hands.",
        "You do not have to leave love behind to move forward. Carry one good value from that person or time into the way you live. Go slowly. If grief stops you from living for a long time, or brings thoughts of harm, ask a trained helper at once. You deserve gentle care.",
        "Today may not be the day when everything feels better. Let it be the day when you breathe, drink water and allow one person to care for you. Small acts of living do not betray what you lost. They carry love forward."
    ), "What loving memory or good quality would you like to carry with you?", "Share one memory with someone safe, then do one kind thing for your body.", R.drawable.icon_compassion),
    KrishnaLetter("rejection", "When You Feel Rejected", "A Closed Door Cannot Reduce You", "Someone’s no may change your path, but it cannot take away your worth.", listOf(
        "My dear one, rejection can feel like the world has said, ‘You are not enough.’ But one person, place or chance cannot hold the full truth about you. Their answer may come from their needs, timing or limits. Feel the hurt, but do not turn it into a name for yourself.",
        "A closed door can turn you toward a new road. I know you cannot see that road yet. Take useful feedback if it is given. Improve what is yours to improve. But do not erase yourself just to win a place where you are not treated with care.",
        "Step away from checking, begging and comparing. Return to the people and duties that still welcome your honest heart. You deserve respect, including from yourself. Keep your heart soft and your limits clear. There are still good people, good work and new doors ahead.",
        "You may not feel ready to hope again. That is all right. Do not force a smile. Just stop asking this one closed door to tell you who you are. Turn gently toward the life that is still calling your name."
    ), "What part of this is useful feedback, and what part is fear speaking?", "Stop one act of checking or comparing and give that time to a good task or safe person.", R.drawable.icon_relationships),
    KrishnaLetter("guilt", "When Guilt Will Not Release You", "Make It Right, Then Rise", "A wrong act asks for truth and change, not endless self-hate.", listOf(
        "My dear one, you wish you could undo something. Guilt can point to what needs care. But it should not tell you that you are only your worst act. You did something wrong; that does not mean you can never become right again. I ask for truth, not a perfect past.",
        "Name what happened. Do not hide it or blame another person. Say sorry without asking them to make you feel better. Repair what you can. Accept fair results. Then change the habit that caused the harm. If anger hurt someone, learn to pause. If a lie hurt trust, begin to speak the truth in small things.",
        "Real regret becomes better action. It does not keep you on the floor forever. Some people may need time or space. Respect that. Once you have owned the wrong and begun to change, let yourself walk toward the light. You deserve the chance to live the lesson you learned.",
        "I do not ask you to forget the lesson. I ask you to stop using it as a weapon against yourself. Let your next honest choice show who you are becoming. Change may be slow, but every true step counts."
    ), "What honest repair or changed action would give your regret a good purpose?", "Write four lines: what I did, who it hurt, how I can repair it, and how I will stop it happening again.", R.drawable.icon_dharma),
    KrishnaLetter("uncertainty", "When the Path Is Uncertain", "You Only Need the Next Right Step", "You do not need the whole road before you begin.", listOf(
        "My dear one, not knowing can make your mind run in every direction. You want a sign that nothing will go wrong. Life cannot give that promise. Bring Me every question. You are not weak because you need time to see clearly.",
        "Place the facts on one side and your fears on the other. Ask: What do I know? What is only a guess? Which choice is honest, kind and true to my duty? Speak with a trustworthy Guru, teacher or elder who will guide you without trying to control you. A true Guru brings light to your understanding; they do not demand that you close your eyes or surrender honest judgment. Then choose the smallest safe step that can teach you more.",
        "You do not need to solve your whole life tonight. Walk the part of the road that you can see. You may change your plan when you learn more. That is wisdom, not failure. I am not only at the end of your journey. I am with you in this calm and honest next step.",
        "Let your mind rest after you have done what you can today. Tomorrow may bring a fact, a person or an idea that you cannot see now. You deserve peace even before every answer arrives. Trust the next right step."
    ), "What is known, what is only feared, and what is your next right step?", "Make three short lists: What I Know, What I Fear, and What I Can Do Today.", R.drawable.icon_strategy),
    personalLetter("anxiety", "When Anxiety Overwhelms You", "Come Back to This Moment", "You do not need to solve every possible future right now.",
        "My dear one, I know how anxiety can make a small thought feel like a great danger. Your body may feel tight, your breath may become fast, and your mind may keep asking, ‘What if?’ You are not weak or broken. Your mind is trying too hard to keep you safe.",
        "Place both feet on the floor. Take a slow breath and name five things you can see. Ask what is happening now, not what fear says may happen later. Write down the real task in front of you. A clear small action can make the future feel less powerful.",
        "Do not carry this alone. Tell a safe person when anxiety keeps stopping sleep, school, work or daily life. A trained helper can teach your mind and body how to feel safe again. Asking for help is wise, and it does not make your faith smaller.",
        "What is true in this moment, before fear adds its story?", "Take five slow breaths, name what is real now, and tell one safe person how you feel.", R.drawable.letters_icon_star),
    personalLetter("lost-hope", "When You Have Lost Hope", "This Dark Hour Is Not the Whole Story", "Hope can begin as one small choice to stay and receive care.",
        "My dear one, I know you are tired of hearing that things will get better when you cannot see how. Hope may feel far away today. You do not need to pretend. Tell Me the truth about the darkness, and let this letter sit beside you without asking you to smile.",
        "Do not make a final judgment about your life from its hardest hour. Pain can narrow your view until one closed door looks like the whole world. Borrow hope from a safe person. Let them help with food, rest, a call, an appointment or the next simple task.",
        "If you may hurt yourself or do not feel safe, contact emergency help or a trusted person now and stay with someone. Your life is precious, and urgent support is an act of courage. Today, hope may be only this: you will not face the next hour alone.",
        "Who can hold hope for you when you cannot hold it alone?", "Contact one safe person now and say clearly, ‘I am not okay, and I need you with me.’", R.drawable.letters_icon_sun),
    personalLetter("heart-broken", "When Your Heart Is Broken", "Love Ending Does Not End You", "You may miss them and still choose the life ahead of you.",
        "My dear one, I know how a broken heart can change every song, place and quiet hour. You may keep asking what you could have done to make them stay. Love can end even when your feelings are real. Their leaving does not prove that you were unworthy of love.",
        "Let yourself grieve without chasing one more answer. Respect their choice and protect your dignity. Step away from checking, old messages and a perfect memory of what was never perfect. Each time you stop reopening the wound, you give your heart a little room to heal.",
        "Return slowly to food, sleep, work, friends and prayer. Healing does not mean the love was false. It means your heart is learning to carry the memory without losing tomorrow. You will not always feel exactly as you do today. Walk gently until that truth becomes real.",
        "What are you ready to stop checking so your heart can rest?", "Move one painful reminder out of daily view and spend time with one safe person.", R.drawable.letters_icon_heart),
    personalLetter("not-enough", "When You Feel You Are Not Enough", "You Do Not Have to Earn Your Worth", "Growth is needed, but self-hate is not the price of growth.",
        "My dear one, perhaps a result, a comment or a comparison has made you feel too small. You may believe you must become smarter, richer, prettier or stronger before you deserve respect. That is pain speaking. Your worth did not arrive with praise, and it cannot leave with criticism.",
        "You can admit where you need to grow without calling your whole self a mistake. Choose one skill to practise and one habit to change. Let correction be clear and kind. A plant grows toward light; it does not grow because someone shouts at its roots.",
        "Notice the good already living in you: the effort you make, the care you show, the truth you are learning to speak. You are unfinished, as every person is. I do not wait for your perfect version. I walk with the honest person you are today.",
        "Whose standard are you using to decide that you are not enough?", "Write three qualities that are already true in you and one skill you will gently practise.", R.drawable.letters_icon_sun),
    personalLetter("misunderstood", "When Nobody Seems to Understand You", "Your Voice Still Deserves a Safe Place", "Being misunderstood does not make your feelings wrong.",
        "My dear one, it is painful to explain your heart and still feel unseen. You may begin to wonder whether speaking is useless. Sometimes people listen only through their own fear, hurry or past. Their poor understanding does not erase the truth of what you feel.",
        "Try again with one safe person and one clear sentence. Say what happened, how it affected you and what you need now. Do not hide your meaning inside hints and do not make your pain louder by using cruel words. Clarity gives understanding its best chance.",
        "Not everyone will understand every part of you. Seek people who are willing to ask, listen and learn. If a person keeps twisting your words, you may step back. You do not need the whole world to agree; you need truth, safe support and respect for your own inner voice.",
        "What is the one sentence you most need someone to hear?", "Write that sentence and share it with one person who usually listens with care.", R.drawable.icon_friendship),
    personalLetter("future-fear", "When You Are Afraid of the Future", "Tomorrow Does Not Need Today’s Fear", "Prepare for what you can and leave unknown things unopened.",
        "My dear one, the future can look like a room filled with shadows. Your mind may create many painful scenes and then react as if they are already real. Most of those scenes are guesses. You are spending today’s strength on battles that may never come.",
        "Ask what can be prepared now. Make the call, save a little, study one part, keep the appointment or ask for advice. Preparation is useful; endless prediction is not. Once today’s duty is done, give your body permission to return to the present.",
        "You have met unknown days before. Help, skill and courage appeared step by step, not all at once. Tomorrow will also arrive one moment at a time. I will not ask you to carry a day before it reaches you. Walk with Me in the day that is here.",
        "Which fear needs a real plan, and which fear needs to be released?", "Take one practical step for a real concern, then spend ten minutes fully in the present.", R.drawable.letters_icon_star),
    personalLetter("life-unfair", "When Life Feels Unfair", "You Can Face Wrong Without Becoming Bitter", "Your pain deserves truth, support and a wise response.",
        "My dear one, some things are unfair. I will not tell you that every wound is secretly easy or that you should smile at injustice. You may have worked honestly and still lost, or been hurt by a choice you did not make. Your anger and sadness need room to speak.",
        "Ask what justice looks like now. It may mean telling the truth, keeping proof, asking for help, setting a limit or protecting someone else. Choose action that repairs rather than revenge that creates more harm. Dharma can be firm without making your heart cruel.",
        "There will also be things you cannot undo. Do not let another person’s wrong decide the kind of person you become. Keep your values, accept support and build what is still possible. Their unfairness belongs to them; your next clean action belongs to you.",
        "What fair and safe action is still in your hands?", "Tell one trusted person the facts and choose one step toward protection, repair or support.", R.drawable.icon_dharma),
    personalLetter("tired-strong", "When You Are Tired of Being Strong", "You Are Allowed to Put the Weight Down", "Rest and help are not failures of courage.",
        "My dear one, perhaps everyone comes to you because you always manage. They see your calm face and do not see how tired you are inside. You may fear that if you stop holding everything, it will all fall apart. Even the strongest arms need somewhere to place their load.",
        "Strength is not doing every task alone. It is knowing what must be done, what can wait and what another person can carry. Say, ‘I need help.’ Cancel one nonessential demand. Rest before your body forces you to stop. Your needs also belong in the room.",
        "You do not have to earn rest by reaching a breaking point. Let someone care for you without quickly returning the favor. I am with you in action, and I am also with you in stillness. Today your brave step may be to soften, receive and breathe.",
        "What weight can you safely put down or share today?", "Ask one person for one specific kind of help and remove one unnecessary task.", R.drawable.icon_compassion),
    personalLetter("self-forgiveness", "When You Cannot Forgive Yourself", "Do Not Turn One Wrong Into a Life Sentence", "Take responsibility, repair the harm and allow change to be real.",
        "My dear one, you may believe that continuing to punish yourself proves you are sorry. It does not repair the past. It only keeps pain active. I ask you to face what happened without excuses, but I do not ask you to hate the person who is trying to become better.",
        "Name the wrong, apologize without pressure and repair what you can. Accept that another person may need time or may not return. Then build a clear practice that makes the same harm less likely. Let your regret become protection, honesty and wiser action.",
        "Forgiving yourself does not mean saying the wrong was acceptable. It means refusing to waste the lesson. You are responsible for the next choice, not able to rewrite the last one. Let changed behavior speak where repeated self-blame cannot.",
        "What repair or changed habit would make your regret useful?", "Write one repair you can offer and one guardrail that will guide your future choices.", R.drawable.icon_dharma),
    personalLetter("betrayal", "When Someone Has Betrayed You", "Their Choice Does Not Make Your Trust Foolish", "You can keep a good heart and build wiser limits.",
        "My dear one, betrayal hurts because you gave someone a safe place in your heart. Now you may feel angry at them and ashamed of yourself for trusting. Do not call your kindness foolish. Trust was a gift you offered. Their misuse of it belongs to their choice.",
        "Do not answer hurt with gossip, public shame or another secret. Learn what truly happened. If it is safe, ask one clear question. A real apology includes ownership, repair and changed action. Words without change do not rebuild trust, no matter how beautiful they sound.",
        "You may forgive and still keep distance. You may care and still say no. Let trust return in small steps only when actions support it. One person’s betrayal does not mean every future friend will do the same. Keep your heart good and your boundaries awake.",
        "What action—not promise—would be needed before trust could grow again?", "Write the boundary you need and share it calmly if the conversation is safe.", R.drawable.letters_icon_heart),
    personalLetter("letting-go", "When You Must Let Someone Go", "Love Can Release What It Cannot Keep", "Letting go can honor both truth and your own dignity.",
        "My dear one, sometimes love remains while a relationship can no longer continue. You may know the truth and still reach back because the empty space frightens you. Letting go is not proof that you never cared. It may be the most honest form your care can take now.",
        "Do not keep opening a door that both people have agreed to close. Say what must be said once, with respect. Return what belongs to them, keep what you learned and reduce the small contacts that keep hope confused. A clear ending is kinder than an endless half-goodbye.",
        "Grief will come in waves. Let safe people stand near you. Build new routines where the old ones lived. You are not throwing love away; you are refusing to turn it into a chain. Release them from the role they cannot fill, and release yourself to live.",
        "What contact or habit is keeping the goodbye unfinished?", "Choose one respectful boundary that gives both hearts space to heal.", R.drawable.letters_icon_heart),
    personalLetter("family-struggling", "When Your Family Is Struggling", "You Can Bring Care Without Carrying Everyone", "Do your part with love, but do not take the whole burden alone.",
        "My dear one, when a family struggles, every room can hold worry. Money, health, conflict or change may make you feel that you must fix everything. You may also feel guilty for having your own needs. You are part of the family, but you are not meant to become its entire support.",
        "Ask what is truly your duty today. Help with one task, speak gently and share facts instead of fear. Let each able person carry a fair part. Seek help from relatives, teachers, doctors, counselors or services when the problem needs more than love alone can provide.",
        "Protect small signs of normal life: a meal together, study time, sleep, a walk or one honest laugh. Difficulty should not be allowed to take every good moment. Your calm care can help the family, and receiving care will help you remain steady.",
        "What is your fair part, and what belongs to someone else?", "Choose one useful family task and ask for help with one burden you cannot carry alone.", R.drawable.icon_relationships),
    personalLetter("stuck", "When You Feel Stuck in Life", "Movement Can Begin Smaller Than You Think", "You do not need a perfect plan to create a little motion.",
        "My dear one, you may feel that every day looks the same while others move ahead. The more you wait for a large answer, the harder any step can feel. Being stuck is often not laziness. It can be fear, tiredness, grief or too many choices pulling at once.",
        "Make the next step very small and visible. Open the document, walk for ten minutes, send the email or clear one corner. Do not ask whether it changes your whole life. Ask whether it creates honest movement. Small motion gives your mind new information.",
        "If you keep trying and cannot function, speak with a safe person or trained helper. You may need support, not stronger blame. Your path has not disappeared because you paused. Begin where your feet are, with what your hands can do today.",
        "What ten-minute action would create real movement?", "Set a ten-minute timer and do only the first physical step of the task.", R.drawable.icon_purpose),
    personalLetter("unanswered-prayers", "When Your Prayers Seem Unanswered", "Silence Is Not Proof That You Are Forgotten", "Prayer can hold your heart even before life gives an answer.",
        "My dear one, you have asked, waited and perhaps begged. Nothing seems to change. You may wonder whether I hear you or whether your faith is too small. Bring Me that doubt too. Honest pain is not disrespect, and you do not need perfect words to pray.",
        "Prayer is not a bargain that controls every result. Sometimes the answer is delayed, different or carried through people and actions you did not expect. Keep doing the practical duty beside the prayer: seek treatment, apply again, apologize, study, ask for help or rest.",
        "I will not promise that every wish will arrive in the shape you chose. I promise that your love, courage and honest effort can still grow in the waiting. Look for the next faithful action, not a hidden sign in every event. Let prayer make you present, not passive.",
        "What practical step can stand beside your prayer today?", "Pray honestly for five minutes, then take one real action connected to the need.", R.drawable.icon_lotus),
    personalLetter("difficult-decision", "When You Are Facing a Difficult Decision", "Let Values Lead Where Fear Cannot", "A clear choice begins with facts, duty and honest consequences.",
        "My dear one, two roads may both hold loss, or many voices may be pulling you in different directions. You want certainty before choosing, but important choices rarely offer it. You can still decide with care, even when you cannot control every result.",
        "Separate facts from guesses. Ask which choice is honest, safe and true to your duty. Consider who may be helped or harmed. Seek a trustworthy Guru, teacher or wise elder who does not gain from your answer. Their importance is not that they choose your life for you, but that they reveal blind spots, ask honest questions and return you to dharma. Notice whether fear, pride or pressure is trying to hurry you.",
        "Choose the best action with the truth available now. You may adjust when new facts appear; that is wisdom, not weakness. Once you have examined the choice well, stop asking worry to provide a perfect promise. Let your values carry the step.",
        "Which choice best protects truth, responsibility and long-term peace?", "Write the facts, duties, likely effects and one wise person you will consult.", R.drawable.icon_strategy),
    personalLetter("lost-purpose", "When You Have Lost Your Purpose", "Meaning Can Start With One Person You Help", "You do not need a grand mission before your day can matter.",
        "My dear one, life may feel like a list of tasks with no reason behind them. You may think everyone else has found a calling while you are only passing time. Purpose is not always a sudden voice. Often it grows quietly through care, learning, work and service.",
        "Look at what is already in your hands: your body, study, family, skill, promise or person who needs you. Do one duty with full attention. Meaning enters ordinary work when it protects, teaches, heals or makes life a little better for someone.",
        "You are allowed to explore. Notice what brings quiet energy, not only quick praise. Ask which problem you are willing to stay with. Your role may change many times while the deeper values under it remain true. Begin by being useful where you stand.",
        "Who or what could be helped by one skill you already have?", "Use one skill for twenty minutes to help a person, place or duty near you.", R.drawable.icon_purpose),
    personalLetter("anger", "When Anger Is Controlling You", "Your Anger Has a Message, Not a Throne", "Listen to what anger protects, then choose your words with care.",
        "My dear one, anger can arrive like fire. It may come because you were hurt, ignored, treated unfairly or pushed too far. The feeling itself does not make you bad. But anger must not become the ruler of your hands, words or choices.",
        "Step away before you reply. Cool your body with water, a walk or ten slow breaths. Then ask, ‘What was I needing?’ Maybe you needed respect, truth, rest or a clear limit. When you know the need, you can speak about it without trying to wound someone.",
        "Say, ‘I felt hurt when this happened. I need us to speak with respect.’ Do not send the cruel message. Do not break what you will later wish to repair. Strong people do not hide anger; they guide it toward truth, safety and fair action.",
        "What hurt or unmet need is hiding under your anger?", "Wait ten minutes before replying, then state the facts, your feeling and your need.", R.drawable.icon_courage),
    personalLetter("comparison", "When You Keep Comparing Yourself", "Another Person’s Light Does Not Dim Yours", "Their success is not proof that you are late or less.",
        "My dear one, comparison can turn another person’s good news into pain. You see their marks, body, money, friends or progress and then look at yourself with cruel eyes. Remember that you are comparing your whole inner life with the small part of theirs that you can see.",
        "Their path has a different time, duty, support and lesson. Bless what is good for them without using it against yourself. Then return to the work that belongs to you. Your life does not become meaningful by looking like someone else’s life.",
        "Notice what comparison is trying to show you. It may point to a goal you truly want, or it may be asking for rest and self-respect. Turn envy into one clean action. Learn, practise or let the false goal go.",
        "What do you truly want beneath the comparison?", "Mute one account that feeds comparison and spend twenty minutes on your own goal.", R.drawable.letters_icon_sun),
    personalLetter("change", "When Change Feels Frightening", "You Can Meet the New One Step at a Time", "Change asks for adjustment, not instant courage.",
        "My dear one, even a good change can make your heart uneasy. The old life was known, and the new one has no familiar shape yet. Fear does not always mean the change is wrong. Sometimes it only means that you care and cannot see the whole road.",
        "Name what will remain steady: your values, a person, a routine, a skill or the way you care for yourself. Then learn one fact about what is coming. A clear detail can make a large unknown smaller. Prepare what you can without trying to control everything.",
        "Give yourself time to become a beginner. You may miss the old and still welcome the new. Those feelings can live together. I am not asking you to love every change. I am asking you to bring your true self into the next small part of it.",
        "What can stay steady while everything else changes?", "Choose one grounding routine and one practical preparation for the change ahead.", R.drawable.letters_icon_star),
    personalLetter("carrying-too-much", "When You Are Carrying Too Much", "Not Every Weight Belongs in Your Hands", "Sort the urgent, share the possible and release the rest.",
        "My dear one, your mind may be holding work, family, money, messages, promises and other people’s feelings all at once. When everything seems important, even a small task feels heavy. This is not proof that you are weak. It is a sign that your load needs sorting.",
        "Write down every burden. Mark what truly needs action today, what can wait and what belongs to another person. Do not keep invisible duties that nobody asked you to carry. A clear list will not solve everything, but it will stop every worry from shouting at the same time.",
        "Ask for specific help. Say no to one demand that breaks your limits. Eat, sleep and pause before exhaustion makes decisions for you. Service is sacred, but destroying yourself is not service. Let your care have wise boundaries so it can remain real.",
        "Which burden is urgent, which can wait, and which is not yours?", "Make three columns—Today, Later and Not Mine—and move each burden into one.", R.drawable.icon_compassion),
    personalLetter("forgotten", "When You Feel Forgotten", "Your Quiet Life Is Still Seen", "A lack of attention does not mean a lack of value.",
        "My dear one, perhaps no one called, thanked you or noticed how much you carried. You may feel easy to replace and hard to remember. Human attention is uneven and often hurried. Its silence can hurt, but it is not a true measure of your place in this world.",
        "Do not test love by disappearing and waiting to see who searches. Reach out honestly. Say, ‘I would like to spend time with you,’ or, ‘I need support today.’ Give people a fair chance to respond to words instead of asking them to read hidden pain.",
        "Also return to the life that knows your touch: a duty, animal, plant, family member, friend or skill. Your presence changes more than applause can show. If one circle keeps overlooking you, widen the circle. There are people who can learn your name and value your care.",
        "Where can you ask to be included instead of waiting silently?", "Invite one safe person to a simple call, walk or meal and say that their company matters.", R.drawable.icon_friendship),
    personalLetter("financial-struggle", "When You Are Struggling Financially", "Your Worth Is Not Your Bank Balance", "Face the numbers with honesty and take one practical step at a time.",
        "My dear one, money fear can enter every part of the day. You may feel ashamed, trapped or afraid to tell anyone. A financial struggle is a real problem, but it is not a moral name for you. Your balance cannot measure your dignity, love or ability to rebuild.",
        "Bring the facts into light. List what comes in, what must go out and which payment is most urgent. Pause new debt and nonessential spending where possible. Speak early with the people or services involved; silence often makes fees, fear and choices harder.",
        "Ask a trusted, financially wise person for help with a simple plan. Avoid promises of quick money that demand secrecy or high risk. Honest work, small savings and patient repair may feel slow, but they protect your future. Take the next clear step without judging your whole life.",
        "What is the most urgent number you need to face clearly?", "Write a basic income-and-needs list and contact one trusted source of practical help.", R.drawable.icon_dharma),
    personalLetter("health-failing", "When Your Health Is Failing", "Your Life Still Holds Dignity and Meaning", "Let care reach your body, mind and heart without shame.",
        "My dear one, illness can change plans, energy and the way you see your body. You may feel angry, afraid or tired of being treated like a problem to solve. You are still a whole person. Your value does not fall when your strength, speed or independence changes.",
        "Seek qualified medical care and share symptoms honestly. Ask questions until you understand the plan. Let someone help with appointments, food, medicine or rest. Prayer can support treatment; it should not replace the skilled care your body needs. Accepting help is not surrender.",
        "Do not force yourself to feel grateful every moment. Make room for grief and for small good things that are still possible. A conversation, sunlight, music or one completed task can hold meaning. I am close to you in the body you have today, not only the body you miss.",
        "What care does your body most clearly need today?", "Write your main symptoms and questions, then contact a qualified health professional or caregiver.", R.drawable.icon_compassion),
    personalLetter("begin-again", "When You Need the Courage to Begin Again", "A New Beginning Can Be Small", "Carry the lesson forward without carrying old shame.",
        "My dear one, starting again can feel heavy because you remember the last attempt. Part of you wants a clean life with no mistakes behind it. You do not need to erase the past. Let it become the teacher that helps you begin with wiser eyes.",
        "Do not wait for perfect energy, perfect timing or perfect courage. Make the beginning so small that fear cannot hide it: one page, one call, one walk, one honest day. A new life is often built from steps that look ordinary.",
        "There may be another difficult day. That does not cancel the start. Return without drama and continue. You are not back at zero; you are returning with knowledge. Be firm with the plan and gentle with the person learning to live it.",
        "What is the smallest clear sign that your new beginning has started?", "Do that one action before the day ends and prepare the next action for tomorrow.", R.drawable.icon_lotus),
    personalLetter("happy", "When You Feel Happy", "Let Your Joy Become Kindness", "Enjoy this bright moment without building your joy on another person’s pain.",
        "My dear one, I am glad that your heart feels light today. Smile, laugh and enjoy what is good. You do not need to feel guilty for being happy. Joy gives your mind fresh strength and reminds you that life also carries beauty, friendship and grace.",
        "But look gently at the roots of your happiness. Let it come from love, honest effort, shared success or a peaceful heart. Never celebrate because someone was hurt, failed, lost or was pushed down. Joy born from another person’s pain will not stay pure for long.",
        "Invite someone into your happiness. Thank the people who helped you. Encourage the person who is still struggling. A good heart can celebrate without boasting and shine without making another person feel small. When your joy becomes kindness, it grows instead of ending with you.",
        "Can your happiness today bring comfort, courage or a smile to someone else?", "Share your joy with one kind act, and do not speak proudly about another person’s loss.", R.drawable.letters_icon_sun),
    personalLetter("grateful", "When You Feel Grateful", "Let Thanks Become Care", "Gratitude is complete when it changes how you treat people and gifts.",
        "My dear one, pause and notice this warm feeling. Something good has reached you through a person, a chance, nature, work or quiet grace. Receive it fully. You do not have to hurry past a blessing or act as if you earned every part of it alone.",
        "Say thank you clearly and, when possible, say exactly what their help changed for you. Remember the hands, time and love behind what you received: parents, family, friends, teachers, a Guru, colleagues, workers and even strangers whose quiet effort made your path easier. Gratitude is more than a happy thought. It means seeing that you did not grow alone, caring for the gift, respecting the giver and refusing to waste what many people may still be praying to have.",
        "Let thanks move through your hands. If you received knowledge, teach. If you received help, help. If you received food, do not waste it. If someone stood by you, stand by another. Gratitude becomes sacred when it turns a blessing into service.",
        "Who or what helped make today better for you?", "Thank one person in clear words and use one gift you have to help someone else.", R.drawable.icon_compassion),
    personalLetter("success", "When You Have Succeeded", "Receive Success Without Losing Yourself", "Celebrate your work, remember your helpers and keep your heart humble.",
        "My dear one, you worked, waited and reached something important. Let yourself feel the joy of that effort. Success is not wrong, and humility does not mean pretending your work did not matter. Honour the discipline, patience and courage that brought you here.",
        "Also remember that no success is made by one person alone. A parent, teacher, Guru, friend, colleague, worker, stranger or unseen blessing helped the road open. Thank them personally; name the help they gave instead of offering only a general word. Gratitude protects success from becoming ego and lets your helpers know that their time and faith mattered. Do not use your new place to mock those behind you or forget the people who loved you before the applause.",
        "Ask what this success now allows you to protect, improve or share. Achievement becomes meaningful when it gives you greater duty, not greater ego. Stay teachable. Keep your promises. Let your character become larger than your title, mark, money or praise.",
        "How can this success make you more useful, not only more visible?", "Thank one helper and use part of your success to open a door for someone else.", R.drawable.icon_purpose),
    personalLetter("proud", "When You Feel Proud of Yourself", "Honour Your Growth, Keep Your Heart Open", "Healthy pride remembers the effort without deciding that you are above others.",
        "My dear one, you may have done something that once felt impossible. Notice the courage, practice or self-control you built. It is healthy to say, ‘I grew.’ You do not need to insult your old self or hide your progress to make other people comfortable.",
        "Hold pride carefully. Let it be warm, not loud. You are not greater than another soul because you did well today. Their struggle may be hidden, and their time may be different. Do not turn your achievement into a weapon, a comparison or a reason to stop learning.",
        "Be proud of the values behind the result: honesty, patience, courage, kindness or discipline. Those qualities can remain even when applause fades. Let this moment prove that growth is possible, then use that belief to face your next duty with a humble mind.",
        "Which quality in you made this growth possible?", "Name that quality, thank someone who supported it, and practise it again today.", R.drawable.icon_courage),
    personalLetter("excited", "When You Feel Excited", "Give Your Energy a Wise Direction", "Excitement is bright energy; let patience and truth guide where it goes.",
        "My dear one, something new is making your mind race ahead. Enjoy that spark. Excitement can help you begin, create and connect. You do not need to make yourself smaller. Let the good energy move through you without allowing it to push every quiet thought away.",
        "Before you promise, buy, post or decide, pause. Excitement can see only the shining part and miss the cost, risk or duty. Check the facts. Sleep on a large choice. Ask whether this path is safe, honest and right for you and the people affected.",
        "Then act with your full heart. Prepare well instead of only imagining the result. Share the news without demanding that everyone feel it in the same way. Energy joined with wisdom becomes steady action; energy without direction often becomes regret.",
        "What simple preparation will help your excitement become real progress?", "Write the next three practical steps and complete the smallest one before making a big promise.", R.drawable.letters_icon_star),
    personalLetter("peaceful", "When You Feel Peaceful", "Protect the Quiet That Helps You See", "Peace is not an empty pause; it is a clear place from which to live well.",
        "My dear one, your mind is quiet for a while. Do not rush to fill every open space with noise, worry or a screen. Rest in this calm. Notice your breath, the sky, a familiar face or the simple safety of this moment.",
        "Peace does not mean that every problem has ended. It means a problem is not ruling you right now. From this clear place, you can see your duty without panic and speak without trying to win. Use calm to make wise choices, not to avoid needed action.",
        "Learn what helped this peace grow. Perhaps it was prayer, sleep, honest work, nature, music, forgiveness or a healthy limit. Keep that practice near you. A peaceful heart can become shelter for others when it listens patiently and acts fairly.",
        "What helped your mind become quiet today?", "Protect ten minutes for that practice and offer your calm attention to one person.", R.drawable.icon_lotus),
    personalLetter("loved", "When You Feel Deeply Loved", "Receive Love and Let It Make You Gentle", "Real love is a gift to cherish, not a possession to control.",
        "My dear one, someone’s care has reached your heart. Receive it. You do not have to doubt every kind word or test whether the person will stay. Let safe, honest love remind you that closeness can be warm, respectful and free from fear.",
        "Do not grip love so tightly that it loses air. A person is not yours to control. Respect their limits, truth, duties and other relationships. Love does not demand passwords, silence or proof through pain. It wants both people to remain safe and whole.",
        "Return love through attention, honesty and steady care. Say what you value. Keep trust sacred. If this love is from family or friendship, do not treat it as less important than romance. Every clean bond can teach your heart how to give without owning.",
        "How can you make a loving bond feel safer and freer today?", "Tell one person what you value about them and respect one need or boundary they have.", R.drawable.letters_icon_heart),
    personalLetter("hopeful", "When You Feel Hopeful", "Turn Hope Into the Next Right Step", "Hope can show the direction; your honest action begins the journey.",
        "My dear one, a small light has returned. Perhaps you can imagine a better result, a healed bond or a new beginning. Welcome that hope. It does not promise that every road will be easy. It tells you that your story still has room to move.",
        "Give hope roots. Learn what the goal asks from you. Make a plan that respects truth, time and your limits. Do not build your whole heart on one exact outcome. Sometimes hope leads to the door you want, and sometimes it gives courage to find another door.",
        "Share hope carefully with people who are hurting. Do not tell them to smile or ignore their pain. Sit beside them, listen and offer one real form of help. Hope is strongest when it makes room for truth and helps someone take a possible step.",
        "What action would show that your hope is becoming real?", "Choose one step you can finish this week and put a clear time beside it.", R.drawable.letters_icon_star),
    personalLetter("relieved", "When You Feel Relieved", "Breathe, Learn and Release", "The danger or pressure has eased; let your body rest and your wisdom remain.",
        "My dear one, something heavy has passed or become smaller. Your body may finally be letting go. Take a slow breath. You do not need to search for the next worry immediately. Relief is your mind’s way of saying that it can put down its guard for a while.",
        "If a difficult result was avoided, look back without shame. What warning, help or choice protected you? Keep that lesson. Relief should not make you careless about a problem that still needs repair. Finish the honest work, apology, plan or safety step that remains.",
        "Then rest. Drink water, eat, sleep or speak with someone who stayed near you. Thank them. You are allowed to enjoy the space after fear. Let relief return you to life with more care, not send you back into the same avoidable danger.",
        "What lesson should remain after this pressure leaves?", "Write one lesson, thank one helper and give your body a quiet period of real rest.", R.drawable.icon_lotus),
    personalLetter("confident", "When You Feel Confident", "Let Confidence Serve the Work", "Trust your ability while leaving room to listen, prepare and learn.",
        "My dear one, you feel ready. This strength may come from practice, experience or finally seeing yourself clearly. Stand tall. Confidence helps you speak, begin and protect what is right. You do not need to shrink so that others will never feel challenged.",
        "Still, confidence is not a promise that you cannot be wrong. Listen to facts. Respect people with less power. Ask questions before you lead. The strongest person in a room can admit, ‘I do not know,’ change a plan and give credit without feeling smaller.",
        "Use your confidence to take responsibility, not to control attention. Invite a quiet person to speak. Defend someone being treated unfairly. Attempt the hard task honestly. When strength protects truth and makes space for others, it becomes courage instead of pride.",
        "Who can feel safer or stronger because you use your confidence well?", "Take one brave action and make room for one other person’s voice while doing it.", R.drawable.icon_courage),
    personalLetter("inspired", "When You Feel Inspired", "Begin Before the Spark Fades", "Inspiration is an invitation; discipline turns it into something useful.",
        "My dear one, an idea, person or truth has awakened you. For a moment, you can see what life might become. Honour that spark. Write it down before noise covers it. Inspiration is precious, but it is only the first breath of a longer work.",
        "Do not wait to feel this powerful every day. Choose a small routine that can continue when the mood becomes ordinary. Study, practise, build or serve at a clear time. A sincere ten minutes repeated often can carry you farther than one bright hour followed by nothing.",
        "Check that your inspiration respects dharma. A beautiful goal should not require lies, harm or neglect of your real duties. If it is good, let it benefit more than your image. Create something that teaches, protects, heals or brings honest beauty into the world.",
        "What useful work is this inspiration asking you to begin?", "Write the idea in one sentence and spend fifteen focused minutes starting it today.", R.drawable.icon_purpose),
    personalLetter("belonging", "When You Feel You Belong", "Help the Circle Grow Wider", "A true place of belonging lets you be yourself and makes room for others too.",
        "My dear one, you have found people or a place where your shoulders can soften. You feel known, welcomed and part of something. Treasure that gift. Belonging gives strength because it tells the heart, ‘You do not have to face every day alone.’",
        "Protect this circle with honesty and care. Do not keep your place by joining gossip, hiding harm or pushing out someone different. A group that needs a victim to feel united is not practising love. Real belonging does not ask you to leave your values outside.",
        "Look for the person standing at the edge. Learn their name. Invite them without forcing them. Share space and listen to a story unlike your own. The safest communities are built when people who feel secure use that security to welcome, defend and include.",
        "Who near you may be waiting for a simple sign that they are welcome?", "Invite one person into a conversation, meal, game or shared task and listen to them.", R.drawable.icon_friendship),
    personalLetter("disappointed", "When You Feel Disappointed", "Let the Hurt Tell the Truth, Not the Future", "Something mattered and did not happen; feel it without deciding that nothing will work.",
        "My dear one, you expected a person, plan or result to meet you, and it did not. Disappointment can feel smaller than grief to others, but your heart knows the hope that was inside it. You are allowed to name the loss without calling yourself foolish.",
        "Separate what happened from the story pain is adding. ‘This did not work’ is a fact. ‘Nothing will ever work’ is fear speaking too widely. Ask what was outside your control, what can be learned and whether the goal still deserves another path.",
        "Do not punish people for promises they never made, but do speak when an agreement was broken. Adjust the plan with clear eyes. Some hopes should be tried again; others should be released. Wisdom is knowing which one protects your values and future.",
        "What fact is true here, and what painful story are you adding to it?", "Write the fact in one line, then choose whether to retry, adjust, ask or release.", R.drawable.letters_icon_sun),
    personalLetter("embarrassed", "When You Feel Embarrassed", "One Awkward Moment Cannot Define You", "You can repair a mistake, laugh gently and return without hiding yourself.",
        "My dear one, your face may feel hot and your mind may replay the moment again and again. You imagine that everyone is still thinking about it. Most people are carrying their own worries. One awkward word, fall or mistake does not become your name.",
        "If you hurt someone, apologise simply and make it right. If nothing harmful happened, let yourself be human. Do not attack yourself to prove that you understand the mistake. Shame rarely teaches better than calm honesty and a clear plan for next time.",
        "Return to the room, class or conversation when it is safe. Avoiding everything gives the moment more power. You may even smile at your own imperfection without making yourself cruel entertainment. Courage sometimes looks like showing up again with a softer heart.",
        "Does this moment need an apology, a lesson or simply release?", "Do the one repair that is needed, then return to one normal activity you were avoiding.", R.drawable.icon_compassion),
    personalLetter("bored", "When You Feel Bored or Restless", "Look Deeper Before You Run From Quiet", "Boredom may be asking for purpose, rest, challenge or your full attention.",
        "My dear one, nothing seems interesting and your hand keeps reaching for quick noise. Do not judge yourself. Boredom can appear when a task is too easy, too hard, repeated too often or disconnected from meaning. It can also come when your mind is tired.",
        "Pause before filling every empty second. Ask what you need: rest, movement, challenge, company or a clearer reason. If a duty must be done, break it into a short round and give it full attention. If you need rest, choose rest that truly refreshes you.",
        "Quiet can also open a door to curiosity. Notice a bird, draw, repair something, read, help at home or learn how an ordinary object works. You do not need constant excitement to be alive. Attention can reveal wonder inside a simple day.",
        "Is your boredom asking for rest, challenge, meaning or connection?", "Choose one screen-free activity for fifteen minutes that answers the real need.", R.drawable.icon_strategy),
    personalLetter("homesick", "When You Miss Home", "Carry Home in the Values You Live", "Distance can hurt, but love and familiar ways can travel with you.",
        "My dear one, you miss familiar voices, food, rooms, streets or the way life felt before you left. Homesickness can arrive even when this new place is good. Missing home does not mean you made the wrong choice. It means your roots matter to you.",
        "Give those roots a living place. Call someone, cook a familiar meal, keep a small ritual or speak your language with a friend. Then gently learn one thing about where you are now. A new place becomes less strange through repeated, ordinary contact.",
        "Do not compare every new person with someone from home. Let new bonds have their own shape. You can love where you came from and still grow where you stand. Home is not only a place behind you; it also lives in the care and values you carry.",
        "What small part of home would comfort you without closing you to this place?", "Keep one familiar ritual today and introduce yourself to one person or place around you.", R.drawable.icon_relationships),
    personalLetter("child-truth", "When You Are Afraid to Tell the Truth", "The Truth Can Bring You Back to Safety", "You may have made a mistake, but hiding it can make fear grow larger.",
        "My dear one, perhaps something broke, a rule was ignored or another person may be upset. Your mind is quickly inventing a different story because you fear punishment. Feeling afraid does not make you bad. But the truth is the first path back toward safety and trust.",
        "Choose a safe adult and begin simply: ‘I need to tell you what really happened.’ Say what you did, what happened next and whether anyone may be hurt. Do not add a new lie to protect the first one. A truthful mistake can be understood, repaired and prevented.",
        "You may still face a fair consequence. Honesty does not erase responsibility; it gives responsibility a clean place to begin. If an adult frightens, threatens or hurts you when you tell the truth, speak to another trusted adult. Truth should lead toward protection, not abuse.",
        "Which safe adult can help you tell the whole truth?", "Use one clear sentence to tell a safe adult what happened and ask how you can repair it.", R.drawable.icon_teachings),
    personalLetter("left-out-school", "When You Feel Left Out at School", "Their Circle Does Not Decide Your Worth", "Being excluded hurts, but you do not have to become unkind to earn belonging.",
        "My dear one, you may see others talking, playing or sitting together while nobody calls your name. That empty feeling can make school seem very long. Please do not decide that you are unworthy because one group did not make space. Your kindness and gifts still belong in this world.",
        "Look for one gentle opening rather than trying to impress everyone. Ask one person a simple question, join an activity you truly enjoy or welcome someone else who is alone. Good friendship often grows quietly between two people before it becomes a larger circle.",
        "If people repeatedly exclude, mock or bully you, tell a parent, teacher or counsellor. You are not creating trouble by asking for help. Stay away from groups that demand cruelty as the price of entry. A place that asks you to harm another person is not true belonging.",
        "Who feels safe enough for one small hello or request to join?", "Speak to one kind person and tell a trusted adult if exclusion or bullying keeps happening.", R.drawable.icon_friendship),
    personalLetter("student-focus", "When You Cannot Focus on Your Studies", "Return to One Small Task", "A wandering mind needs a clear beginning, not more insults.",
        "My dear one, the page is open but your attention keeps moving toward the phone, a worry or anything except the work. Do not call yourself lazy too quickly. Your mind may be tired, anxious, confused or overwhelmed by a task that has no clear starting point.",
        "Make the beginning small. Choose one question or one page. Put the phone away, set a short timer and keep only the material you need in front of you. When attention wanders, notice it and return. The return itself is the exercise that builds concentration.",
        "After the focused period, take a real break and check what blocked you. Ask a teacher or trusted adult when you do not understand. If attention problems affect many parts of life for a long time, qualified support may help. Difficulty focusing is not a moral failure.",
        "What is the smallest study task you can clearly finish now?", "Remove one distraction and complete one twenty-minute focus period followed by a five-minute break.", R.drawable.icon_mind),
    personalLetter("important-exam", "Before an Important Exam", "Carry Preparation, Not Panic", "The exam matters, but it cannot measure your entire worth or future.",
        "My dear one, your mind may be trying to sit every question before the exam has even begun. Preparation is useful; repeating disaster in your imagination is not. Return to the next topic, the next practice question and the next healthy hour that is actually in your hands.",
        "Do not trade sleep, food and calm for desperate last-minute study. A tired mind cannot use what it knows well. Review the essentials, prepare what you need and stop at a sensible time. During the exam, breathe, read carefully and begin with what you understand.",
        "Afterward, do not punish yourself by replaying every uncertain answer. The work is complete for now. Remember to thank the parent, teacher, Guru, friend or sibling who explained, encouraged, provided time or quietly believed in you. Their help does not reduce your effort; recognising it makes your achievement more honest and your heart more humble. One result may guide the next method, but it cannot name your intelligence, goodness or purpose. I remain with you in the result you want and the result you must learn from.",
        "What preparation is still useful, and what worry can now be released?", "Complete one focused review, prepare your materials and protect a full period of sleep.", R.drawable.icon_gita),
    personalLetter("youth-peer-pressure", "When Friends Pressure You", "Belonging Should Not Cost Your Values", "A crowd cannot make a harmful choice safe or right.",
        "My dear one, perhaps they are laughing, daring you or saying that everyone does it. You fear that one no will make you look weak or alone. Remember that pressure often hides behind jokes. Anyone who demands your health, honesty, body or safety is not protecting your friendship.",
        "You do not need a long debate. Say, ‘No, I am not doing that,’ move toward a safer place and contact someone you trust. If the pressure involves substances, dangerous driving, sexual activity, violence or an unsafe secret, leave and seek adult help immediately.",
        "It may hurt to lose a group. But standing alone for a moment is better than losing your judgment inside their approval. Look for people who can enjoy life without demanding self-betrayal. The friendships worthy of you will leave room for your no.",
        "Which value or safety limit is this pressure asking you to betray?", "Practise one clear refusal and save the contact of a person who can help you leave safely.", R.drawable.icon_courage),
    personalLetter("identity-confusion", "When You Do Not Know Who You Are", "You Are Allowed to Be Unfinished", "Identity can grow through values, honest experience and time.",
        "My dear one, people may keep asking what you will become, where you belong or why you are not like someone else. You may not have a clear answer. Uncertainty does not mean emptiness. It can be the honest space in which you discover what is truly yours.",
        "Notice what makes you feel alive, what kind of harm you refuse to cause and which duties you can perform with sincerity. Try skills, meet different people and learn without forcing every experience into a permanent label. You can change your understanding as you grow.",
        "Do not let a crowd, relationship or online image define you before you have listened to your own values. Seek safe guidance without giving another person ownership of your life. Your identity can hold family, faith, questions, gifts and change without becoming a contradiction.",
        "Which three values do you want your life to express, whatever path you choose?", "Write three values and take one small action that makes one of them visible today.", R.drawable.icon_purpose),
    personalLetter("parent-failing", "When You Feel You Are Failing as a Parent", "Your Next Repair Matters More Than Perfection", "A parenting mistake can become a place for humility, repair and growth.",
        "My dear one, you may remember the shouting, missed signs or response you wish you could take back. Comparison shows you other families only from the outside and then calls you unworthy. Your child does not need a parent who protects a perfect image. They need a parent willing to see and repair.",
        "Name the exact mistake without adding excuses: ‘I shouted. That was frightening and wrong.’ Listen to the child’s experience. Offer a repair and explain what you will do differently. An apology does not remove your authority; it teaches that authority also answers to truth.",
        "Then seek the help you need. Exhaustion, trauma, conflict or mental-health strain may require support, not more private shame. Change one repeatable response rather than making a dramatic promise. A calmer pause, a weekly conversation or professional guidance can begin changing the home.",
        "What specific response do you need to repair rather than hide?", "Give one complete apology and write one practical change you will use in the same situation next time.", R.drawable.icon_compassion),
    personalLetter("child-pulls-away", "When Your Child Is Pulling Away", "Keep the Door Open Without Chasing", "Growing independence changes connection; it does not always mean love has disappeared.",
        "My dear one, the child who once told you everything may now answer with one word, close a door or turn first toward friends. Fear may urge you to question every silence. Some distance is part of growth, while some silence may signal hurt that deserves attention.",
        "Offer connection without interrogation. Invite them for tea, a drive or a simple task beside you. Ask one open question and do not fill the quiet immediately. Respect ordinary privacy while keeping clear safety boundaries around danger, abuse, substances and serious mental distress.",
        "Do not use guilt to pull them close. Let your care become dependable: calm when truth arrives, firm when safety matters and interested in who they are becoming. If the change is sudden, extreme or joined by warning signs, seek qualified support rather than assuming rejection.",
        "What kind of connection might feel safe rather than demanding to your child?", "Offer one low-pressure shared activity and listen without giving advice unless it is requested.", R.drawable.icon_relationships),
    personalLetter("work-taken-over", "When Work Has Taken Over Your Life", "Your Duty Should Not Consume the Person Performing It", "Work matters, but health, relationships and inner life are also responsibilities.",
        "My dear one, work may be the first thought in the morning and the last screen at night. Even rest feels like falling behind. Sincere duty is sacred, but endless availability is not the same as excellence. A life built only around output eventually weakens the person doing the work.",
        "Look honestly at what is required, what is ambition and what has become fear. Set one stopping point, protect food and sleep and communicate realistic expectations. If the workplace depends on permanent emergency, document the pattern and seek responsible support or a safer path where possible.",
        "Return your attention to someone or something that cannot be measured as productivity. Speak with family, walk, pray or sit without performing. Your career can use your gifts without owning your identity. Rest is not stolen time when it protects judgment, health and clean action.",
        "Which part of work is true duty, and which part is fear refusing to stop?", "Set one clear end time today and give thirty undistracted minutes to health, relationship or silence.", R.drawable.icon_karma),
    personalLetter("work-unseen", "When Your Work Is Not Recognised", "Unseen Work Still Has Value", "Seek fairness without allowing missing praise to poison your purpose.",
        "My dear one, you may have solved problems, supported others or carried responsibility while someone else received the attention. It is natural to feel hurt. Humility does not require pretending unfairness is acceptable or allowing your contribution to be repeatedly erased.",
        "Gather the facts and ask for a calm conversation. Describe your contribution, request clear feedback and discuss credit, role or growth directly. Avoid attacking another person’s success or making hidden effort the only form of communication. People cannot always recognise work they are never shown.",
        "If recognition still does not come, decide what the situation teaches about this place. Continue with integrity while exploring healthier opportunities if needed. Do not let resentment turn careful work into careless work. Your worth is larger than a title, but fair treatment still deserves a clear voice.",
        "What recognition, feedback or fairness do you need to request clearly?", "Write the facts of your contribution and ask for one specific professional conversation.", R.drawable.icon_leadership),
    personalLetter("couple-arguments", "When Every Conversation Becomes an Argument", "Pause the Battle and Find the Need", "A relationship cannot heal while both people are fighting only to win.",
        "My dear one, the argument may begin with one small issue and quickly collect every old wound. Both people speak louder because neither feels heard. Stop before cruel words become new evidence against the relationship. A pause is not abandonment when you clearly promise to return.",
        "When calm, describe one event without labels such as always or never. Name the feeling and need beneath it. Then listen until you can repeat the other person’s concern fairly. Understanding does not require agreement, but it prevents you from fighting an imagined version of each other.",
        "Agree on one practical change and a time to review it. If there are threats, control, violence or fear, prioritise safety and qualified support; communication techniques do not solve abuse. Love can hold disagreement, but it must not be used to demand endurance of harm.",
        "What need are you trying to express beneath the repeated argument?", "Request a twenty-minute calm conversation about one issue and agree on one specific change each.", R.drawable.letters_icon_heart),
    personalLetter("rebuilding-trust", "When Trust Needs to Be Rebuilt", "Trust Returns Through Truth Repeated Over Time", "An apology can begin repair, but consistent behaviour must carry it forward.",
        "My dear one, perhaps a lie, hidden choice or broken promise changed the safety of your bond. Both hearts may want quick relief, but trust cannot be commanded back to its old place. The person harmed needs room for questions, boundaries and their own pace.",
        "If you caused the harm, tell the complete truth without making the other person comfort you. Accept reasonable transparency and repair what can be repaired. If you were harmed, decide what evidence of change you need. Forgiveness does not force immediate access or remove wise limits.",
        "Choose small promises that can be kept consistently. Review progress without reopening the wound as a weapon in every disagreement. Some relationships can rebuild; others may need distance. Seek qualified help when the breach is serious, repeated or connected with abuse.",
        "What consistent behaviour would make trust safer—not merely quieter?", "Agree on one clear promise, one boundary and a date to review whether behaviour is changing.", R.drawable.icon_relationships),
    personalLetter("elder-invisible", "When Age Makes You Feel Invisible", "Your Presence Still Carries Meaning", "Attention may change with age, but dignity and spiritual worth do not become smaller.",
        "My dear one, conversations may move quickly around you, decisions may be made without asking and the world may praise only what is new. This can hurt deeply. The years you carry are not empty time. They hold labour, loss, love, mistakes and wisdom no hurried glance can measure.",
        "Ask to be included where your voice matters. Share experience without demanding that younger people copy every path. Look for places where your knowledge, listening or presence is welcomed. A child, neighbour, community or family member may need what only patient attention can offer.",
        "Also allow yourself to receive new learning and companionship. Age does not require retreat from curiosity. If loneliness becomes heavy, tell someone clearly and seek community or professional support. You deserve more than being remembered only when somebody needs a task completed.",
        "Where would you like your voice or presence to be welcomed more fully?", "Ask one person for meaningful time together and offer one story, skill or listening presence.", R.drawable.letters_icon_sun),
    personalLetter("depending-on-others", "When You Must Depend on Others", "Receiving Care Does Not Reduce Your Dignity", "Needing help can change your routine, but it does not erase your value or voice.",
        "My dear one, perhaps illness, age or circumstance now makes you ask for help with tasks you once did easily. You may fear becoming a burden. Remember that human life has always moved through giving and receiving. Independence was never the only proof that your life mattered.",
        "Name your preferences and keep the choices still available to you. Ask helpers to speak with you, not around you. Accept care with thanks while also expressing discomfort or limits clearly. Good care protects dignity and does not use dependence as permission for control.",
        "Let relationships include more than tasks and medicine. Share a memory, ask about another person’s day, pray, laugh or offer advice when invited. If anyone neglects, frightens, exploits or hurts you, tell another trusted person or responsible service. Dependence never cancels your right to safety.",
        "Which choice or preference would help you feel more respected in your care?", "Tell a caregiver one preference clearly and receive one needed form of help without apologising for existing.", R.drawable.icon_compassion),
    personalLetter("caring-for-ill", "When You Are Caring for Someone Who Is Ill", "Your Care Matters, and So Does Your Life", "Love can serve deeply without requiring the caregiver to disappear.",
        "My dear one, your day may be organised around medicines, appointments, uncertainty and interrupted sleep. Others may ask about the person who is ill and forget to ask how you are. The care you give is real, but exhaustion is not the only proof that your love is sincere.",
        "Write down what must be done and what can be shared. Ask relatives, friends or services for specific help instead of saying only that things are difficult. Protect food, rest, medical needs and one small part of life that belongs to you. A depleted caregiver also deserves care.",
        "You may feel love, anger, fear and tiredness in the same hour. These feelings do not make you disloyal. Speak with someone safe and seek professional support when the load becomes unmanageable. If care needs exceed your ability, asking for trained help is responsible, not abandonment.",
        "Which part of the care load can another person safely carry?", "Ask one person for one specific task and protect one uninterrupted period of rest this week.", R.drawable.icon_compassion),
    personalLetter("grief-returns", "When Grief Returns Unexpectedly", "A Returning Wave Does Not Erase Your Healing", "A date, song or place can awaken love and pain without warning.",
        "My dear one, you may have felt steadier and then suddenly found yourself crying as if the loss were new. Do not call this failure. Grief does not move in a straight line. The heart remembers through seasons, anniversaries, sounds and ordinary moments that once belonged to two people.",
        "Let the wave pass through without deciding that it will last forever. Name what awakened it. Share a memory, sit quietly, pray or contact someone who understands. Care for the body with water, food and rest. You do not need to make the feeling productive.",
        "When the wave softens, return gently to the duty or relationship still in your hands. Continuing life does not betray the person you miss. If grief remains overwhelming, dangerous or prevents daily living for a long time, trained support can walk beside spiritual care.",
        "What memory or moment is asking to be honoured today?", "Share one memory with a safe person and choose one gentle act of care for your present life.", R.drawable.letters_icon_heart),
    personalLetter("leader-decision", "When Others Depend on Your Decision", "Let Power Listen Before It Acts", "A leader’s choice should protect people, truth and long-term welfare—not merely appearance.",
        "My dear one, people may be waiting for your answer while you carry facts they cannot see. The pressure to appear certain can become stronger than the desire to be wise. Slow down enough to understand who will bear the cost of the decision, especially those with less power.",
        "Invite honest disagreement and ask what evidence would change your mind. Separate the needs of the mission from the needs of your ego. A popular decision can still be wrong, and an uncomfortable decision can still require compassion, explanation and a plan to reduce harm.",
        "Then decide and take responsibility. Do not hide behind the team when the choice was yours or claim all credit when it succeeds. Review the result and correct course when facts change. Leadership becomes service when authority remains answerable to dharma.",
        "Whose voice or consequence have you not yet considered?", "Ask one affected person with less authority for honest input before making or confirming the decision.", R.drawable.icon_leadership),
    personalLetter("faith-dry", "When Your Faith Feels Dry", "Honesty Can Be a Form of Devotion", "You do not have to pretend to feel close to Krishna in order to keep walking sincerely.",
        "My dear one, prayer may feel like words returning from an empty room. A practice that once brought warmth may now feel ordinary or distant. Do not force emotion or use another person’s devotion to judge your own. A quiet season does not prove that love has ended.",
        "Bring Me the truth: ‘I do not feel You, but I am here.’ Read one verse slowly, sit for one minute or perform one kind action without demanding a spiritual experience. Devotion can remain through honest practice when strong feeling is absent.",
        "Examine whether exhaustion, grief, disappointment or unanswered questions need care. Speak with a wise, trustworthy person who allows questions without fear. Faith that has never been allowed to ask may remain fragile. Let your questions deepen truth rather than drive you into shame.",
        "What honest question or disappointment have you been afraid to bring into prayer?", "Write one honest prayer and complete one small act of service without waiting to feel inspired.", R.drawable.icon_lotus),
    personalLetter("moving-on", "When It Is Time to Move On", "A Finished Chapter Does Not Need to Become a Prison", "Some people arrive as blessings, some bring lessons, and some are not meant to stay forever.",
        "My dear one, not everyone who enters your life is meant to remain forever. Some people come as blessings. They bring love, help, wisdom and good memories. Some come as lessons. They show you where you need stronger limits, more courage or more respect for yourself.",
        "Even medicine has an expiry date. Something that once helped you may not always remain good for you. In the same way, a friendship, relationship, habit or dream may have served its purpose and reached its end. Do not hold it only because it was once important. Honour the good, learn from the pain and look honestly at what it has become today.",
        "You do not need to hate someone in order to leave. You do not need to call every ending a failure. If a person keeps draining your peace, hurting your dignity or pulling you away from dharma, you may step back with a clean heart. Forgive where you can, keep wise limits and move forward without revenge. Letting go does not erase love or thanks; it means you will not force a finished chapter to continue.",
        "What are you holding because it was once good, even though it is no longer healthy?", "Write what this person or season gave you, what it taught you and one boundary that will help you move forward.", R.drawable.icon_life_journey),
    personalLetter("comfort-growth", "When Comfort Is Keeping You Small", "Comfort Should Restore You, Not Control You", "Rest is needed, but avoiding every hard step can slowly make your world smaller.",
        "My dear one, rest is important, but life cannot always be built around comfort. If you avoid every hard task, difficult talk and uncertain step, your world slowly becomes smaller. Comfort should help you recover. It should not become a cage.",
        "A seed must break before it can grow. The body becomes stronger through effort. The mind becomes wiser by facing problems. You do not need to search for pain, but do not run from every struggle. Some hard moments are preparing you for a larger duty.",
        "Ask yourself: ‘Is this truly unsafe, or is it only uncomfortable?’ Protect yourself from real harm. But when the path is safe and right, take the step even if your heart is afraid. I will walk with you.",
        "Which comfort is stopping you from growing?", "Do one useful task today that you have been avoiding because it feels difficult.", R.drawable.icon_courage),
    personalLetter("happiness-before-duty", "When You Are Waiting to Feel Happy Before You Begin", "You Can Act Before the Perfect Mood Arrives", "A meaningful life includes pain, doubt and effort as well as happiness.",
        "My dear one, no meaningful life is happy every hour. Even strong people feel fear, loss, doubt and pain. Greatness does not mean smiling through everything. It means staying honest and choosing the right action even when the heart feels heavy.",
        "Happiness is a beautiful visitor, but it cannot be your only guide. If you act only when you feel good, your goals will remain unfinished. Duty, love and courage sometimes ask you to move while you are tired, sad or unsure.",
        "Do not feel ashamed of pain. Listen to what it is teaching you and seek help when it becomes too heavy. Then ask, ‘What is still in my hands?’ You may not control the whole situation, but one wise action can begin to change it.",
        "Are you waiting to feel happy before doing what matters?", "Complete one important duty today without waiting for the perfect mood.", R.drawable.letters_icon_sun),
    personalLetter("pain-strength", "When Pain Makes You Question Your Strength", "Understand the Pain Before You Answer It", "Pain may ask for care, change, courage or release; it does not automatically mean weakness.",
        "My dear one, pain does not always mean you are on the wrong path. Sometimes it shows that something mattered. Sometimes it warns you to stop. Sometimes it teaches you to prepare better, choose better people or build stronger limits.",
        "Do not worship pain, and do not ignore it. Understand it. Ask whether you need rest, treatment, protection, support or courage. Wisdom knows the difference between pain that helps you grow and harm that asks you to leave.",
        "You are not weak because something hurts. Strength begins when you face the truth about the pain and choose the next healthy step. Cry if you need to. Ask for help. Rest when needed. Then rise without hating yourself for having fallen.",
        "What is your pain asking for—care, change, courage or release?", "Write the lesson this pain is teaching you and one safe action you can take.", R.drawable.icon_compassion),
    personalLetter("smart-work", "When Hard Work Is Not Giving Results", "Join Effort with Wisdom", "Working harder is not always the answer; effort needs the right direction and method.",
        "My dear one, working harder is not always the answer. If you keep walking in the wrong direction, more speed will only take you farther away. Effort needs wisdom.",
        "Pause and study your method. What is working? What is wasting time? What skill is missing? Ask a teacher, Guru or experienced person to show you what you cannot see. Guidance can save months of blind effort.",
        "Smart work is not lazy work. It means choosing the right task, using the right method and giving it full attention. Remove distractions. Practise the weak part. Measure progress. Change the plan when facts show a better way, but do not leave a good goal only because it became difficult.",
        "Do you need more effort, a better method or wise guidance?", "Stop one low-value activity and give that time to the task that will create the greatest real progress.", R.drawable.icon_strategy),
    personalLetter("someone-only-takes", "When Someone Only Comes to Take", "Love Needs Giving and Receiving", "Care should not leave one heart carrying every need, every call and every repair.",
        "My dear one, you may notice that someone comes when they need time, money, comfort or help, but disappears when you need care. You keep giving because you are kind, and then feel empty or used. Kindness is precious, but it does not require you to ignore a one-sided pattern.",
        "Look at actions over time. Have you clearly shared what you need? Have they listened, helped or changed? One hard season can make a good person need more support, so do not judge too quickly. But repeated taking without care, thanks or respect needs an honest limit.",
        "Say what you can and cannot give. Offer only what is healthy and truly yours to offer. Do not lend what you cannot safely lose or hide serious harm to protect their image. A person who values you may not like every limit, but they will learn to respect that you are a person, not a resource.",
        "Does this bond make room for your needs as well as theirs?", "Say one clear limit and notice whether the person answers with respect, guilt or pressure.", R.drawable.icon_relationships),
    personalLetter("presence-costs-peace", "When Their Presence Costs You Peace", "Peace Needs Truth, Not Pretending", "Some discomfort helps relationships grow; repeated fear and disrespect do not.",
        "My dear one, your body may become tense before this person calls or enters the room. You may rehearse every word because small things often become blame, control or conflict. Do not dismiss what your body is telling you, but do not decide from one difficult day alone.",
        "Ask what the pattern has been. Can you speak honestly without fear? Do they respect your no? Is repair possible after harm? A healthy bond can include disagreement, challenge and growth. It should not require you to lose sleep, hide truth or become smaller to keep another person calm.",
        "Set a clear limit and seek wise support. If there is threat, violence, stalking, control or abuse, choose safety and trained help rather than a private meeting. You can wish someone well from a distance. Protecting peace is not avoiding every problem; it is refusing to let repeated harm become normal.",
        "Is your peace disturbed by healthy growth, or by a repeated pattern of harm?", "Write the pattern in facts and share it with one trusted person who will support truth and safety.", R.drawable.icon_inner_peace),
    personalLetter("returning-to-hurt", "When You Keep Returning to What Hurt You", "A Familiar Door Can Still Lead to Pain", "Returning does not make you foolish, but the pattern deserves more than another promise.",
        "My dear one, perhaps you left and returned, blocked and called again, or promised yourself that this time would be different. Familiar pain can feel less frightening than an empty space. Hope may keep holding one good memory while your mind pushes repeated harm aside.",
        "Do not shame yourself. Shame often sends people back into the same cycle. Write what happened each time, what was promised and what truly changed. Trust steady actions, not only tears, gifts or beautiful words that appear when you are about to leave.",
        "Make the next choice with support. Tell someone safe, remove easy paths back to danger and seek trained help when abuse, addiction or strong emotional dependence is involved. Missing a person does not mean returning is wise. You can feel love, grief and longing while still choosing protection.",
        "What facts does hope keep asking you to forget?", "Write the repeated pattern and ask one safe person to help you keep the boundary you choose.", R.drawable.icon_chakra),
    personalLetter("friendship-changed", "When a Friendship Is No Longer the Same", "Not Every Distance Needs an Enemy", "Friendships can change through time, growth and new duties without making the past false.",
        "My dear one, a friend who once knew every part of your day may now call less, reply differently or seem far away. You may wonder what you did wrong. Sometimes there is hurt that needs a talk. Sometimes two lives simply begin moving at a different pace.",
        "Ask once with care: ‘I feel distance between us. Is something wrong?’ Listen without preparing a defence. If repair is needed, be honest. If life has changed, do not force closeness through guilt, constant checking or reminders of everything you once shared.",
        "Thank the friendship for what it gave. Leave the door open if the bond is still kind, but also make room for new people and duties. A changing friendship does not erase the laughter, help or growth it carried. You may honour the old bond without demanding its old shape.",
        "Does this friendship need a repair, a new shape or a gentle goodbye?", "Have one honest talk, then give equal energy to a relationship that is present and caring now.", R.drawable.icon_friendship),
    personalLetter("outgrown-place", "When You Have Outgrown a Place", "Growth Can Honour Where It Began", "A place can be good for an earlier season and still become too small for your next duty.",
        "My dear one, a job, group, town or role may once have helped you feel safe and useful. Now you may feel called to learn more, serve differently or live with greater truth. Leaving can bring both excitement and guilt, especially when good people helped you there.",
        "Do not confuse growth with being better than those who stay. Ask whether you are moving toward a real value or only running from ordinary effort. Finish duties cleanly, give fair notice, share what others need and thank the people who opened the first door.",
        "Then allow yourself to go. You can carry the good habits, friendships and lessons without keeping the same walls around your life. Roots do not ask a tree to remain a seed. Let gratitude look backward while courage takes the next honest step forward.",
        "Are you leaving to grow toward dharma, or only escaping a difficulty that will follow you?", "Write what you are moving toward, complete one duty well and thank one person who helped you grow here.", R.drawable.icon_life_journey),
    personalLetter("guilty-choosing-self", "When You Feel Guilty for Choosing Yourself", "Self-Care Is Not the Same as Selfishness", "Your health, safety and honest limits are also part of your duty.",
        "My dear one, you may have learned that love means always saying yes. When you rest, decline a request or choose a path others dislike, guilt quickly calls you selfish. But a life spent meeting every demand can leave no strength for your true duties, health or purpose.",
        "Look honestly at the choice. Are you avoiding a fair duty, or protecting a real need? Selfishness ignores others. Healthy self-care includes others without erasing you. You may keep a promise and still ask for help. You may love family and still refuse disrespect, danger or control.",
        "Explain your limit with kindness, but do not argue forever for permission to have one. People who benefited from your silence may call your change unkind. Let steady, fair actions show the truth. Care for yourself so that what you give comes from strength, not fear and hidden anger.",
        "Is this guilt pointing to a real duty, or punishing you for having a healthy limit?", "Name the duty you will keep and the limit that will protect your health, safety or peace.", R.drawable.icon_compassion),
    personalLetter("memories-pull-back", "When Memories Keep Pulling You Back", "Remember Without Leaving Today", "The past can be honoured without becoming the only place where your heart lives.",
        "My dear one, a song, place, message or quiet hour may carry you back so fully that today disappears. Some memories bring warmth. Others reopen regret and longing. You may keep replaying them because the past feels known while the present still feels empty.",
        "Do not fight every memory. Sit with it for a moment and name what you miss: the person, safety, hope or version of yourself. Keep the lesson and the love. Then notice what the memory leaves out, including the pain, limits or duties that also belonged to that time.",
        "Return through your senses. Feel your feet, look around and name the date. Call someone present, complete one task or create one new memory with care. If painful memories take over daily life, sleep or safety, seek trained help. You deserve support in returning to now.",
        "What do you truly miss beneath the memory?", "Honour one memory for ten minutes, then give one full hour to a person or duty in your life today.", R.drawable.letters_icon_star),
    personalLetter("closure-never-came", "When the Closure You Wanted Never Came", "You Can Close Your Side of the Door", "An apology or answer may never arrive, but your life does not have to wait beside it.",
        "My dear one, you may still be waiting for them to explain, admit the harm or say the words that would make everything clear. Your mind keeps building one more conversation. Closure feels as if it is locked inside another person’s honesty, and they may never offer it.",
        "Accepting this is not saying the harm was right. It means facing what their actions have already shown. Write the questions that remain and answer only what the facts allow. Some blanks must stay blank. Do not fill them with blame against yourself.",
        "Make closure through your own truth: name what happened, choose the lesson, set the limit and stop returning for an answer that costs more peace each time. A counsellor, elder or trusted friend can witness your story. You do not need the person who hurt you to agree before healing begins.",
        "Which answer are you still asking another person to give before you permit yourself to move?", "Write the answer supported by their actions, choose one boundary and stop one form of checking for seven days.", R.drawable.icon_lock),
    personalLetter("love-trust-gone", "When Love Remains but Trust Is Gone", "Love Does Not Remove the Need for Safety", "A heart may still care while wise judgment requires proof, limits or distance.",
        "My dear one, you may still love someone who lied, broke a promise or made you feel unsafe. This can be confusing. Love does not switch off the moment trust breaks. But love alone cannot rebuild what repeated actions damaged.",
        "Trust returns slowly through truth, open answers, kept promises and respect for your limits. Do not rush because they are sorry or because you miss the good days. If you caused the harm, accept that the other person may need time. If you were harmed, you may watch actions without offering full access.",
        "Some bonds can heal with steady repair and trained help. Some need distance or an ending, especially when harm continues. Forgiveness does not require forgetting facts. You may keep love in your heart while choosing a boundary that protects your body, mind and future.",
        "What action—not promise—would be needed for trust to become safer?", "Write one clear boundary and one steady action required before giving more trust.", R.drawable.icon_relationships),
    personalLetter("beginning-betrays-past", "When Beginning Again Feels Like Betraying the Past", "Moving Forward Can Carry Love With It", "A new life does not erase the person, dream or season that mattered before it.",
        "My dear one, you may fear that smiling again, loving again or building a new dream means the past mattered less. Part of you stays close to pain because pain feels loyal. You may believe that moving forward leaves someone or something precious behind.",
        "Love is not measured by how long you refuse life. Carry one value, habit, story or kindness from what you lost. Let it shape the person you become. The past can travel as wisdom and love; it does not need to travel as a weight that stops every new step.",
        "Go slowly. A new beginning does not demand that you forget or feel happy every day. It asks only that you allow today to have meaning too. Speak the memory, keep what is sacred and open one small space for a person, duty or hope that is here now.",
        "What part of the past can you carry as love instead of pain?", "Choose one value from the past and live it through one new action this week.", R.drawable.icon_lotus),
    personalLetter("rise-again", "When You Are Ready to Rise Again", "Rise With the Lesson, Not the Weight", "Falling is not your final story; one honest step can begin your return.",
        "My dear one, I saw what brought you down. I saw the effort nobody noticed and the pain you hid behind your smile. But this moment is not the end of your story. Falling does not make you weak, and needing time to stand does not make you less worthy.",
        "Rise slowly. You do not need to become strong in one day. Take one honest step, then another. Do not carry yesterday as a punishment. Carry its lesson. Ask what must change, accept wise help and begin again with a calmer mind and better understanding.",
        "I am not asking you to prove anything to the world. I am asking you to trust the strength growing within you. Rest if you need rest, but do not build a home inside defeat. Your life still has work, love and dharma waiting for your hands.",
        "What is one lesson you can carry forward without carrying the shame?", "Choose one small action that says, ‘I am beginning again,’ and complete it today.", R.drawable.icon_courage),
    personalLetter("stronger-than-moment", "When This Moment Feels Bigger Than You", "This Moment Cannot Decide Your Whole Life", "Fear may be loud today, but it does not know your full strength or future.",
        "My dear one, this moment may feel powerful. Your mind may be showing you every danger at once and saying that you cannot handle what comes next. Pause. You have already crossed days you once thought you could never survive. The strength that carried you then has not left you.",
        "Do not try to solve your whole life in one frightened hour. Calm your breath and look only at the next right step. Ask for help where it is needed. Do what is within your control with care, and stop fighting the parts of tomorrow that have not arrived.",
        "A hard moment can reveal strength that comfort never asked you to use. Let this day teach you steadiness, patience and trust. The problem may be real, but fear does not get to decide who you become while facing it.",
        "What is the next right step hidden inside this frightening moment?", "Take five slow breaths, write the one thing you can control and do it before returning to the larger worry.", R.drawable.icon_mind),
    personalLetter("life-purpose", "When You Want Your Life to Matter", "Purpose Begins With the Good Near You", "A meaningful life is built through honest duties, service and gifts shared with care.",
        "My dear one, you may be waiting for one great purpose to appear. You may think your life will matter only through fame, wealth or a large achievement. But meaning often begins quietly: protecting someone, teaching what you know, keeping a promise or doing needed work with love.",
        "Look at the duty standing near you. Study sincerely. Work honestly. Care for your family, nature and every living being. Help the person whose need you can truly meet. A lamp does not ask how many people will praise its light. It shines because giving light is its nature.",
        "Your purpose may grow and change, but your values can guide every stage. Use your skills to make life a little safer, wiser or kinder. No sincere act of service is too small to carry meaning. The good you do may travel farther than you ever see.",
        "Who or what near you can receive the best of your care today?", "Use one skill, hour or kind action to help a person, animal, place or duty near you.", R.drawable.icon_lotus),
    personalLetter("choose-courage", "When Courage Is Calling You", "Choose What Is Right Even While You Tremble", "Courage is not the absence of fear; it is dharma becoming stronger than fear.",
        "My dear one, courage does not mean that fear has disappeared. It means you choose what is right while your heart is still trembling. You may need to speak the truth, defend someone, admit a mistake, ask for help or begin something uncertain. Do not wait to feel perfectly fearless.",
        "Let dharma guide your courage, not anger, pride or the wish to look powerful. Be firm without being cruel. Protect the innocent without creating needless harm. Speak clearly, listen wisely and step away safely when danger needs responsible help rather than a lonely fight.",
        "Your shaking voice can still tell the truth. Your small action can still change another person's fate. Courage grows each time you act from values instead of fear. Begin with the brave choice that belongs to you, not with an image of how heroes should look.",
        "What right action is fear asking you to delay?", "Tell one safe person your plan, then take one calm and responsible step toward the right action.", R.drawable.icon_courage),
    personalLetter("ready-to-grow", "When You Are Ready to Grow", "Move Toward the Light Without Hating Where You Began", "Growth starts with honest self-seeing, patient practice and one better choice at a time.",
        "My dear one, growth begins when you stop hiding from what needs to change. Do not be ashamed of your weak places. See them clearly and work on them patiently. A seed does not hate itself for being small. It simply keeps reaching toward the light.",
        "Accept useful correction without calling yourself worthless. Learn from a teacher, elder or trusted Guru. Practise what is difficult. Leave habits that weaken your mind, body or character. You do not need to change everything tonight; you need to keep one honest promise today.",
        "Do not compare your growth with another person's journey. Your starting point, duties and pace are your own. Measure yourself by truth, steady effort and the good your choices create. Every disciplined return is proof that change is already happening.",
        "Which habit or weakness is asking for patient and honest work?", "Choose one small practice you can repeat daily for seven days and mark today's first effort.", R.drawable.icon_lotus),
    personalLetter("walk-dharma", "When the Right Path Feels Lonely", "Walk in Dharma Even Without the Crowd", "Popularity can change quickly; the peace of a clean heart stays with you.",
        "My dear one, sometimes dharma will ask you to refuse what everyone else accepts. You may be laughed at for refusing to cheat, lie, bully, harm your body or join a cruel joke. The crowd may call your values weakness because your choice makes them examine their own.",
        "Do not mistake popularity for truth. Walk gently, but do not abandon your character to gain approval. Say no clearly. Leave when needed. Ask a trusted adult or responsible person for help if the situation is unsafe. Standing for dharma does not mean facing every danger alone.",
        "Choose friends who respect your health, honesty and future. Be patient with those who do not understand, but do not hand them control of your direction. The discomfort of standing apart will pass; the strength of keeping your values will travel with you.",
        "Which value must you protect even if others do not approve?", "Write your clear ‘no’ in one sentence and share it with a trusted person who will support you.", R.drawable.icon_dharma),
    personalLetter("dream-discipline", "When Your Dream Needs Discipline", "Let Daily Practice Carry the Dream", "A dream becomes real through focused effort, wise methods and promises kept on ordinary days.",
        "My dear one, a dream cannot grow through wishes alone. It needs your time, focus and steady effort. Some days you will feel inspired; other days you will not. Do the honest work on both. Discipline is the promise you keep after excitement becomes quiet.",
        "Plan wisely. Remove one distraction, break the work into clear parts and learn from people who understand the path. Rest when your body needs it, but do not make comfort your permanent home. Smart work means checking your method, accepting feedback and improving instead of only becoming tired.",
        "Do not waste today's strength worrying about the final result. Give your full heart to the duty in front of you. Your dream is asking whether you are willing to grow into the person who can carry it with skill, patience and humility.",
        "What daily practice would make your dream stronger even when motivation is absent?", "Schedule one focused work period today, remove one distraction and finish a clear task.", R.drawable.icon_chakra),
    personalLetter("valuable-gift", "When You Wonder What You Can Give", "The World Needs the Good You Can Offer", "Your time, skill, attention and kindness can become sacred when used in service.",
        "My dear one, never believe that you have nothing valuable to offer. You may not have great wealth or influence, but you have attention, time, skills, kindness and courage. A patient listener can lighten a lonely heart. One brave voice can protect someone from harm.",
        "Notice what comes naturally to you and what you are willing to learn well. Your gift may be teaching, building, caring, organising, creating, listening or solving a problem others avoid. Strengthen it through practice, then offer it where it can truly help rather than only attract praise.",
        "Do not hide your light because another person shines differently. Their gift does not reduce yours. Offer your ability without pride and receive correction without shame. A talent becomes meaningful when it lifts life beyond the person who owns it.",
        "Which ability or quality in you could serve someone beyond yourself?", "Use one gift for thirty minutes this week to teach, protect, help or create something useful.", R.drawable.icon_compassion),
    personalLetter("future-still-open", "When One Result Makes Your Future Look Closed", "Your Future Is Larger Than One Result", "An exam, rejection or mistake can guide your next step, but it cannot name your whole future.",
        "My dear one, one result may be making every road look closed. An exam, interview, rejection or mistake can tell you what happened once. It cannot tell you everything you can become. Do not turn a painful result into a permanent name for yourself.",
        "Let the result teach you. Ask what knowledge, practice, timing or method needs to change. Seek honest feedback from a teacher, Guru or skilled person. Prepare again when the goal is still right, or choose a different path when wisdom shows that your gifts belong elsewhere.",
        "Some doors close because they are not your road. Others ask you to return better prepared. Have the patience to learn the difference. Your future is not one narrow doorway; it is built through values, skills, relationships and many choices still waiting to be made.",
        "Is this result asking you to prepare again, change your method or notice another path?", "Ask one wise person for specific feedback and write the next practical step before the day ends.", R.drawable.icon_life_journey),
    personalLetter("next-step-strength", "When You Need Strength to Take the Next Step", "You Only Need Enough Light for One Step", "Faith does not remove action; it gives you strength to begin before the whole road is clear.",
        "My dear one, you do not need to see the entire road before you begin. You only need enough faith to take the next right step. Do not wait for every doubt to disappear. Begin with what you know and let honest action reveal what comes after.",
        "Make the call, open the book, offer the apology, ask for help or start the work. Choose the action that follows truth and duty, not the one that only gives quick relief. If the step carries serious risk, seek wise guidance and make a safe plan before moving.",
        "My presence does not mean you should remain still and wait for Me to do your duty. I give you steadiness, people, wisdom and chances; your hands must still act. One sincere step today can become a road when you return tomorrow.",
        "What is the smallest right step you already know you need to take?", "Do that step within the next hour, then write the next one while your courage is awake.", R.drawable.icon_next)
)

fun krishnaLetter(id: String?): KrishnaLetter = krishnaLetters.firstOrNull { it.id == id } ?: krishnaLetters.first()
